E["item:ambassador-infernus-bracer"] = {t="item",n="Ambassador Infernus' Bracer",z="badlands",s="In the Badlands, Advisor Belgrum asks you to bring back a sign of Ambassador Infernus' defeat. He hopes to send aid to the troubled excavation at Uldaman.",h="In the Badlands, Advisor Belgrum asks you to bring back a sign of Ambassador Infernus' defeat.",sec={{t="Proof from Angor",b="Historian Karnik sends you to Angor Fortress in the Badlands to destroy Ambassador Infernus. Ragnaros sent the ambassador to oversee Shadowforge's search for lost artifacts in Uldaman. The excavation has already cost many lives, and Karnik fears those artifacts could threaten Ironforge. Bring the bracer back to Advisor Belgrum as proof, so Belgrum can send aid to the site.",sp=0}},faq={{q="What is Ambassador Infernus' Bracer?",a="Ambassador Infernus' Bracer is proof of the ambassador's defeat, carried back to Advisor Belgrum in Ironforge.",al={"infernus bracer","ambassador bracer","what's the bracer"}},{q="Where do I find the bracer?",a="The bracer comes from Ambassador Infernus at Angor Fortress in the Badlands.",al={"bracer location","where is infernus","get the bracer"}},{q="Who wants the bracer?",a="Historian Karnik asks you to bring the bracer to Advisor Belgrum in Ironforge as proof of Ambassador Infernus' defeat.",al={"who needs bracer","belgrum bracer","turn in bracer"}},{q="Why is Ambassador Infernus in the Badlands?",a="Ragnaros sent Ambassador Infernus to oversee Shadowforge's search for lost artifacts in Uldaman.",al={"why infernus here","infernus badlands","what's he doing"}},{q="Why does Ironforge want the ambassador defeated?",a="The Shadowforge excavation has caused many casualties, and Historian Karnik fears the recovered artifacts could be used against Ironforge.",al={"why kill infernus","ironforge threat","what's the danger"}},{q="What happens after I bring it to Belgrum?",a="Belgrum thanks you and says he will send word to Historian Karnik and arrange aid for the Badlands excavation site.",al={"after bracer","belgrum turn in","what next"},sp=1}},ang={["race:Dwarf"]="As a dwarf, you carry proof of a threat to Ironforge: Shadowforge's search in Uldaman has already cost dwarven lives."},kw={"advisor belgrum","ambassador infernus","angor fortress","badlands","bracer","infernus bracer","ironforge","ragnaros","shadowforge","uldaman"},rel={"quest:762","quest:725","subzone:uldaman","zone:badlands"},src={"Wowpedia: Ambassador Infernus' Bracer","An Ambassador of Evil"}}
E["item:black-drake-s-heart"] = {t="item",n="Black Drake's Heart",z="badlands",s="In Lethlor Ravine, a black drake's heart carries the heat Sigrun Ironhew needs for his fiery weapon enchantments. He asks you to bring one from the ravine's drakes.",h="In Lethlor Ravine, a black drake's heart carries the heat Sigrun Ironhew needs for his fiery weapon...",sec={{t="A Smith's Request",b="Sigrun Ironhew learned a fiery enchantment from his former teacher, Feranor Steeltoe. To use the technique, he needs blood from a rare black drake whelp's still-beating heart. Bring him one from Lethlor Ravine, and he will show you the enchantment.",sp=0}},faq={{q="What is a Black Drake's Heart for?",a="Sigrun Ironhew needs its blood to teach you a fiery weapon enchantment.",al={"black drake heart use","why heart","heart for sigrun"}},{q="Where can I find one?",a="Scorched Guardians and Scalding Whelps in Lethlor Ravine can yield a Black Drake's Heart.",al={"black drake heart location","where heart","get drake heart"}},{q="Who is Sigrun Ironhew?",a="Sigrun Ironhew is an apprentice of Feranor Steeltoe, who taught him a special technique for imbuing weapons with fiery enchantments.",al={"sigrun","ironhew who","sigrun backstory"}},{q="What does the enchantment do?",a="It lets weapons strike with searing heat.",al={"fiery blaze enchantments effect","weapon fire","what enchantment"}}},ang={["faction:Alliance"]="Sigrun Ironhew offers to teach you his fiery weapon enchantment if you bring him a black drake's heart from Lethlor Ravine."},kw={"black drake's heart","feranor steeltoe","fiery blaze enchantments","lethlor ravine","scalding whelp","scorched guardian","sigrun ironhew"},rel={"quest:706","subzone:lethlor-ravine","zone:badlands"},src={"Wowpedia: Black Drake's Heart","Fiery Blaze Enchantments"}}
E["item:blacklash-s-bindings"] = {t="item",n="Blacklash's Bindings",z="badlands",s="Blacklash's Bindings are sought by those trying to end the danger posed by the drakes of Lethlor Ravine.",h="Blacklash's Bindings are sought by those trying to end the danger posed by the drakes of Lethlor Ravine.",sec={{t="A Drakeslayer's Proof",b="In Lethlor Ravine, Blacklash's Bindings mark the end of a black drake's imprisonment and the danger that followed. The seal holding Blacklash and Hematus depends on three runestones taken from nearby pillars with the Sign of the Earth. Once the seal is broken, both drakes are freed. Their bindings are then brought back as proof of Blacklash's death.",sp=0}},faq={{q="What are Blacklash's Bindings?",a="Blacklash's Bindings are a keepsake taken from the black drake after his death in Lethlor Ravine.",al={"blacklash bindings","what is the binding","blacklash's stuff"},sp=1},{q="Who is Blacklash?",a="Blacklash is a black drake imprisoned with Hematus beneath the Seal of the Earth in Lethlor Ravine.",al={"blacklash backstory","who's blacklash","black drake blacklash"}},{q="Where do the bindings come from?",a="The bindings come from Blacklash in the Badlands.",al={"where bindings from","blacklash drop","get bindings"},sp=1},{q="Why are the bindings wanted?",a="Those seeking to end the danger from Blacklash and Hematus ask for the bindings as proof that Blacklash is dead.",al={"why need bindings","bindings for what","blacklash quest item"},sp=1},{q="How were Blacklash and Hematus freed?",a="The Sign of the Earth lets its bearer take three runestones from the pillars in Lethlor Ravine. Placing them in the Seal of the Earth frees both drakes.",al={"free the drakes","how seal broken","runestones and seal"},sp=1}},kw={"badlands","black drake","blacklash","blacklash's bindings","lethlor ravine","runestones","seal of the earth","sign of the earth"},rel={"zone:badlands","subzone:lethlor-ravine","topic:black-dragonflight","quest:717","quest:782","item:chains-of-hematus","item:sign-of-the-earth"},src={"Wowpedia: Blacklash's Bindings","Tremors of the Earth (2)","Broken Alliances (2)"}}
E["item:bonegrip-s-note"] = {t="item",n="Bonegrip's Note",z="badlands",s="In Ironforge, Gerrig Bonegrip writes down the three relics he needs. The note lets him keep their names from unwelcome ears.",h="In Ironforge, Gerrig Bonegrip writes down the three relics he needs.",sec={{t="Written Names",b="Gerrig Bonegrip asks you to bring three items of power to him in Ironforge. He will not speak their names aloud, for ears may be listening. Instead, he writes them on Bonegrip's Note and gives it to you.",sp=0}},faq={{q="What is Bonegrip's Note?",a="Bonegrip's Note is a written list of three items of power Gerrig Bonegrip needs.",al={"bonegrip note","what's the note","bonegrip's paper"}},{q="Who wrote the note?",a="Gerrig Bonegrip wrote the note so he would not have to speak the relics' names aloud.",al={"who made this note","gerrig's note","who's bonegrip"}},{q="What does Gerrig need?",a="Gerrig needs the Star of Xil'yeh, the Hand of Dagun, and the Legacy Heart.",al={"what items are listed","three relics","what's on the note"}},{q="Why are the names written down?",a="Gerrig says ears may be listening, so he writes down the relics' names instead of speaking them.",al={"why won't he say them","ears on us","secret item names"}}},ang={["faction:Alliance"]="As an Alliance traveler, you can gather the relics on Gerrig's note and bring them to him in Ironforge."},kw={"bonegrip's note","gerrig bonegrip","hand of dagun","ironforge","legacy heart","star of xil'yeh","three relics"},rel={"npc:gerrig-bonegrip","quest:736","item:hand-of-dagun","item:star-of-xil-yeh","item:the-legacy-heart","zone:badlands"},src={"Wowpedia: Bonegrip's Note","The Star, the Hand and the Heart (Alliance)"}}
E["item:bracers-of-rock-binding"] = {t="item",n="Bracers of Rock Binding",z="badlands",s="Bracers of Rock Binding are stone bindings taken from greater rock elementals in the Badlands. Lotwil Veriatus needs them to measure the strength of his own shackles.",h="Bracers of Rock Binding are stone bindings taken from greater rock elementals in the Badlands.",sec={{t="Stone Bindings",b="Lotwil Veriatus studies the greater rock elementals in the Badlands for the elemental shackles he is building. He believes their bracers can help him gauge how strong his own shackles are. Five will give him spares for his research, since his assistant Servo is known to misplace reagents and notes.",sp=0}},faq={{q="What are the Bracers of Rock Binding?",a="They are stone bracers taken from greater rock elementals in the Badlands. Lotwil Veriatus studies them to gauge the strength of his own shackles.",al={"rock bracers","stone bindings","bracers item"}},{q="Who wants these bracers?",a="Lotwil Veriatus wants five Bracers of Rock Binding for his research into the strength of his shackles.",al={"who needs them","Lotwil bracers","who wants rock bindings"}},{q="Why does Lotwil need them?",a="Lotwil Veriatus believes the greater rock elementals' bracers will help him measure the strength of his own shackles.",al={"why bracers","Lotwil research","what for"}},{q="Where do the bracers come from?",a="Greater rock elementals in the Badlands carry Bracers of Rock Binding.",al={"where get bracers","rock elemental bracers","where are they"}},{q="Why does Lotwil ask for five?",a="Lotwil asks for five so he has extras for his research, as his assistant Servo is notorious for misplacing reagents and research.",al={"how many bracers","need five","why so many"}}},kw={"badlands","bracers of rock binding","greater rock elemental","lotwil veriatus","rock bracers","servo","shackles"},rel={"quest:710","npc:lotwil-veriatus","zone:badlands"},src={"Wowpedia: Bracers of Rock Binding","Study of the Elements: Rock (3)"}}
E["item:buzzard-gizzard"] = {t="item",n="Buzzard Gizzard",z="badlands",s="Buzzard gizzards are reagents gathered from the buzzards of the Badlands. Jarkal Mossmeld in Kargath needs them to replenish his alchemical stocks.",h="Buzzard gizzards are reagents gathered from the buzzards of the Badlands.",sec={{t="A Needed Reagent",b="Jarkal Mossmeld, an alchemist in Kargath, asks for five buzzard gizzards to replenish his stocks. The Badlands buzzards yield them, alongside the other reagents he seeks. Bring the gizzards to Jarkal with the rest of his requested supplies.",sp=0}},faq={{q="Who wants buzzard gizzards?",a="Jarkal Mossmeld, an alchemist in Kargath, needs five buzzard gizzards to replenish his stocks.",al={"who needs gizzards","Jarkal gizzards"}},{q="Where do buzzard gizzards come from?",a="Buzzards in the Badlands yield gizzards. Giant Buzzards, Buzzards, Starving Buzzards, and Wayward Buzzards are known to have them.",al={"gizzard location","where gizzards","buzzard bits"}},{q="What are buzzard gizzards used for?",a="Jarkal Mossmeld uses buzzard gizzards as alchemical reagents to replenish his stocks.",al={"gizzard use","why gizzards","alchemist reagents"}},{q="How many gizzards does Jarkal need?",a="Jarkal Mossmeld asks for five buzzard gizzards.",al={"gizzard count","how many buzzard bits","five gizzards"}}},ang={["faction:Horde"]="As a member of the Horde, you can bring the Badlands reagents Jarkal Mossmeld needs to Kargath."},kw={"alchemist","badlands","buzzard","buzzard gizzard","jarkal mossmeld","kargath","reagent"},rel={"zone:badlands","subzone:kargath","quest:2258","item:crag-coyote-fang","item:rock-elemental-shard"},src={"Wowpedia: Buzzard Gizzard","Badlands Reagent Run (Horde)"}}
E["item:chains-of-hematus"] = {t="item",n="Chains of Hematus",z="badlands",s="The Chains of Hematus are bindings found in Lethlor Ravine. Garek or Gorn seeks them alongside Blacklash’s bindings in the Badlands.",h="The Chains of Hematus are bindings found in Lethlor Ravine.",sec={{t="A Broken Seal",b="In Lethlor Ravine, the Chains of Hematus are returned after Hematus is freed from the Seal of the Earth. Three runestones taken from the ravine’s pillars unlock that seal. Garek or Gorn seeks the chains alongside Blacklash’s bindings, once the two black drakes have been slain.",sp=0}},faq={{q="What are the Chains of Hematus?",a="The Chains of Hematus are bindings taken from the black drake Hematus in Lethlor Ravine.",al={"hematus chains","chains item","hematus bindings"}},{q="Where do I find the Chains of Hematus?",a="Hematus in Lethlor Ravine, in the Badlands, bears the Chains of Hematus.",al={"where chains","chains location","hematus item"}},{q="Why are the chains wanted?",a="Garek or Gorn asks for the Chains of Hematus alongside Blacklash’s bindings after the drakes are slain.",al={"why chains wanted","chains for what","need hematus chains"},sp=1},{q="How is Hematus freed?",a="The runestones from the Pillars of Diamond, Opal, and Amethyst are placed in the Seal of the Earth, freeing Hematus and Blacklash.",al={"free hematus","seal of earth","runestones"},sp=1},{q="Who wants the chains?",a="Garek or Gorn seeks the Chains of Hematus, depending on who sent you to Lethlor Ravine.",al={"who needs chains","garek chains","gorn chains"}}},kw={"badlands","black drake","chains of hematus","hematus","lethlor ravine","runestones","seal of the earth"},rel={"item:blacklash-s-bindings","item:sign-of-the-earth","subzone:lethlor-ravine","zone:badlands","quest:717"},src={"Wowpedia: Chains of Hematus","Tremors of the Earth (2)","Broken Alliances (2)"}}
E["item:coyote-jawbone"] = {t="item",n="Coyote Jawbone",z="badlands",s="A coyote jawbone marks a crag coyote hunted in the Badlands. Neeka Bloodscar seeks them to keep the beasts from raiding Kargath's food supplies.",h="A coyote jawbone marks a crag coyote hunted in the Badlands.",sec={{t="A Kargath Keepsake",b="Crag coyotes prowl the dusty plains of the Badlands, and some creep into Kargath for food. Neeka Bloodscar asks you to bring her their jawbones. She says the beasts are tough prey, and the hunt may show whether you can survive in this harsh land.",sp=0}},faq={{q="What is a Coyote Jawbone?",a="A Coyote Jawbone comes from a crag coyote in the Badlands. Neeka Bloodscar asks for them in Kargath.",al={"coyote bone","jawbone item","coyote jaw"}},{q="Why does Neeka want the jawbones?",a="Crag coyotes creep into Kargath and steal scraps from the food supplies. Neeka wants their jawbones as proof of the hunt that helps keep the coyotes away.",al={"why jawbones","neeka wants bones","what for"}},{q="Where can I find the coyotes?",a="Crag coyotes roam the dusty plains of the Badlands.",al={"coyote location","where coyotes","badlands coyotes"}},{q="Who is Neeka Bloodscar?",a="Neeka Bloodscar is in Kargath and asks for crag coyote jawbones to protect the outpost's food supplies.",al={"neeka","bloodscar","who wants bones"}},{q="Are crag coyotes easy prey?",a="No. Neeka calls crag coyotes a tough breed and says they are not easy prey.",al={"hard coyotes","tough prey","coyote difficulty"}}},kw={"badlands","coyote jawbone","coyote thieves","crag coyote","food supplies","kargath","neeka bloodscar"},rel={"quest:1419","zone:badlands","subzone:kargath","quest:1418"},src={"Wowpedia: Coyote Jawbone","Coyote Thieves"}}
E["item:crag-coyote-fang"] = {t="item",n="Crag Coyote Fang",z="badlands",s="A Crag Coyote Fang comes from coyotes in the Badlands. Jarkal Mossmeld in Kargath needs ten for his alchemical supplies.",h="A Crag Coyote Fang comes from coyotes in the Badlands.",sec={{t="A Badlands Reagent",b="Jarkal Mossmeld, an alchemist in Kargath, asks for Crag Coyote Fangs to replenish his stocks. The fangs come from Crag Coyotes, Elder Crag Coyotes, Feral Crag Coyotes, and Rabid Crag Coyotes in the Badlands. He needs ten, along with buzzard gizzards and rock elemental shards.",sp=0}},faq={{q="Where do Crag Coyote Fangs come from?",a="Crag Coyote Fangs come from Crag Coyotes, Elder Crag Coyotes, Feral Crag Coyotes, and Rabid Crag Coyotes in the Badlands.",al={"crag fang source","coyote teeth","where fang"}},{q="Who wants Crag Coyote Fangs?",a="Jarkal Mossmeld, an alchemist in Kargath, asks for ten Crag Coyote Fangs to replenish his stocks.",al={"who needs fangs","jarkal fangs","fangs for who"}},{q="Why does Jarkal need the fangs?",a="Jarkal Mossmeld needs Crag Coyote Fangs as reagents to replenish his alchemical stocks.",al={"why fangs","jarkal needs what","alchemist supplies"}},{q="What else does Jarkal ask for?",a="Jarkal also asks for five Buzzard Gizzards and five Rock Elemental Shards.",al={"other reagents","what else jarkal","badlands ingredients"}}},kw={"badlands","crag coyote","crag coyote fang","elder crag coyote","feral crag coyote","jarkal mossmeld","rabid crag coyote","reagent"},rel={"quest:2258","zone:badlands","subzone:kargath","item:buzzard-gizzard","item:rock-elemental-shard"},src={"Wowpedia: Crag Coyote Fang","Badlands Reagent Run (Horde)"}}
E["item:crumpled-scroll-fragment"] = {t="item",n="Crumpled Scroll Fragment",z="badlands",s="The Crumpled Scroll Fragment is one piece of the ruined Scroll of Myzrael, sought by Theldurin the Lost in the Badlands. The fragments may be needed to face the danger Myzrael poses.",h="The Crumpled Scroll Fragment is one piece of the ruined Scroll of Myzrael, sought by Theldurin the Lost in...",sec={{t="A Fragment Found",b="Enraged Rock Elementals in the Badlands carry pieces of the destroyed Scroll of Myzrael. Theldurin the Lost seeks the torn, singed, and crumpled fragments, hoping they can be joined again. He fears Myzrael may already be free, and says the scroll could be needed to trap her once more.",sp=0}},faq={{q="What is the Crumpled Scroll Fragment?",a="The Crumpled Scroll Fragment is one of three pieces of the destroyed Scroll of Myzrael, found among Enraged Rock Elementals in the Badlands.",al={"crumpled fragment","scroll piece","what is this fragment"}},{q="Who wants the fragment?",a="Theldurin the Lost asks you to bring him the Crumpled Scroll Fragment along with the Torn and Singed Scroll Fragments.",al={"who needs this","give fragment to who","theldurin fragments"}},{q="Where did the scroll fragments come from?",a="Enraged elementals stole the Scroll of Myzrael and tore it into pieces. They now fight over its fragments.",al={"fragment origin","why elementals have scroll","scroll got torn"}},{q="Why does Theldurin want the fragments?",a="Theldurin hopes the fragments can be joined again. He believes the Scroll of Myzrael may be needed to trap Myzrael if she is free.",al={"why collect these","why does he need scroll","myzrael scroll purpose"}}},kw={"badlands","crumpled scroll fragment","enraged rock elemental","myzrael","scroll fragment","scroll of myzrael","theldurin the lost"},rel={"quest:692","item:scroll-of-myzrael","item:singed-scroll-fragment","item:torn-scroll-fragment","npc:theldurin-the-lost","zone:badlands"},src={"Wowpedia: Crumpled Scroll Fragment","The Lost Fragments"}}
E["item:elemental-shard-sample"] = {t="item",n="Elemental Shard Sample",z="badlands",s="The Elemental Shard Sample bears markings that may help Lotwil Veriatus investigate the machines in the Burning Steppes. It carries a clue from the Badlands to a scholar's camp east of you.",h="The Elemental Shard Sample bears markings that may help Lotwil Veriatus investigate the machines in the...",sec={{t="A Marked Shard",b="The initials G.L.A. and a rank mark distinguish the shard from the machines found in the Burning Steppes. The Elemental Shard Sample reaches Lotwil Veriatus at his camp to the east, where the scholar studies elemental sciences. The mark may aid the search for whoever made the machines.",sp=0}},faq={{q="What is the Elemental Shard Sample?",a="It is a shard bearing the initials G.L.A. and a rank marking, taken from a machine in the Burning Steppes.",al={"elemental shard","shard sample"}},{q="What does G.L.A. mean?",a="G.L.A. is imprinted on the elemental shards, but its meaning is not known here.",al={"gla meaning","shard initials"}},{q="What rank are the machines?",a="The machines destroyed in the Burning Steppes bear Rank IV markings, thought to be a low rank.",al={"rank iv","machine rank"}},{q="Who should receive the sample?",a="Lotwil Veriatus, a scholar of some renown in elemental sciences, is meant to examine the sample.",al={"who wants the shard","lotwil shard"}},{q="Where is Lotwil Veriatus?",a="Lotwil Veriatus is stationed at a camp east of you.",al={"lotwil location","camp to the east"}},{q="Why does the sample matter?",a="The shard's markings may help Lotwil assist in the search concerning the machines in the Burning Steppes.",al={"why shard matters","machine clue"}}},kw={"burning steppes","elemental sciences","elemental shard","elemental shard sample","g.l.a.","lotwil veriatus","rank iv"},rel={"quest:4062","npc:lotwil-veriatus","zone:badlands"},src={"Wowpedia: Elemental Shard Sample","The Rise of the Machines (2)"}}
E["item:hammertoe-s-amulet"] = {t="item",n="Hammertoe's Amulet",z="badlands",s="Hammertoe’s Amulet is a dwarf’s keepsake from his search into Uldaman’s past. In the Badlands, it carries his work onward to those who knew him.",h="Hammertoe’s Amulet is a dwarf’s keepsake from his search into Uldaman’s past.",sec={{t="A Dwarf’s Charge",b="Wounded in the Badlands, Hammertoe asks you to carry his amulet to Prospector Ryedol. Hammertoe had been searching for the origins of his people and trying to stop the Shadowforge clan from finding the scrolls. Ryedol knows of that work, and Hammertoe trusts him to decide what must be done.",sp=0},{t="In Ironforge",b="After hearing what happened to Hammertoe, Ryedol sends you to Historian Karnik in Ironforge. Karnik and Hammertoe had worked together to find lost artifacts in Uldaman. The amulet carries their work into Karnik’s hands, and he sees that it bears on more than grief for his companion.",sp=0}},faq={{q="Who was Hammertoe?",a="Hammertoe was a dwarf searching for the origins of his people in Uldaman. He also worked to keep the Shadowforge clan from finding the scrolls.",al={"hammertoe dwarf","who's hammertoe","hammertoe story"}},{q="Why does Hammertoe give me his amulet?",a="Hammertoe asks you to take the amulet to Prospector Ryedol in the Badlands. Ryedol knows about Hammertoe’s search and can decide what to do next.",al={"why amulet","hammertoe's amulet why","what do i do with amulet"}},{q="Who is Prospector Ryedol?",a="Prospector Ryedol is the dwarf Hammertoe trusts with his amulet and his work in Uldaman.",al={"ryedol who","prospector guy","who's ryedol"}},{q="Why is the amulet important?",a="The amulet belonged to Hammertoe and represents his work searching Uldaman for the origins of his people. Ryedol and Historian Karnik know that work.",al={"amulet importance","what's special about it","amulet matter"}},{q="Who is Historian Karnik?",a="Historian Karnik is in Ironforge and worked with Hammertoe to find lost artifacts in Uldaman. Ryedol directs you to him with the amulet.",al={"karnik who","historian guy","who's karnik"}},{q="What was Hammertoe trying to stop?",a="Hammertoe sought to stop the Shadowforge clan from finding the scrolls in Uldaman.",al={"shadowforge goal","why stop shadowforge","scrolls in uldaman"}}},ang={["race:Dwarf"]="As a dwarf, Hammertoe’s search for the origins of his people touches your own heritage. His amulet carries that work to the scholars who knew him."},kw={"amulet","badlands","dwarves","hammertoe","historian karnik","prospector ryedol","scrolls","shadowforge clan","uldaman"},rel={"quest:723","zone:badlands","subzone:uldaman","npc:prospector-ryedol","quest:720","zone:ironforge"},src={"Wowpedia: Hammertoe's Amulet","Prospect of Faith","Prospect of Faith (2)"}}
E["item:hand-of-dagun"] = {t="item",n="Hand of Dagun",z="badlands",s="The Hand of Dagun is a relic sought by Gerrig Bonegrip in Ironforge. It is one of three items he requests in exchange for Yagyin's Digest.",h="The Hand of Dagun is a relic sought by Gerrig Bonegrip in Ironforge.",sec={{t="A Relic for Bonegrip",b="Gerrig Bonegrip asks for the Hand of Dagun alongside two other relics. He needs all three before he will give you a copy of Yagyin's Digest, a text tied to beginning a new chapter of his order.",sp=0}},faq={{q="What is the Hand of Dagun?",a="The Hand of Dagun is a relic Gerrig Bonegrip requests with the Star of Xil'yeh and the Legacy Heart.",al={"hand of dagun","dagun hand","what's the hand"}},{q="Who wants the Hand of Dagun?",a="Gerrig Bonegrip in Ironforge asks you to bring him the Hand of Dagun and two other relics.",al={"who wants dagun's hand","bonegrip hand","who needs it"}},{q="Why does Gerrig Bonegrip need it?",a="Gerrig needs the Hand of Dagun as one of three relics he requests before giving you a copy of Yagyin's Digest.",al={"why bonegrip wants it","why need hand","what's it for"}},{q="What does the Hand of Dagun do?",a="The Hand of Dagun is said to carry a poison that mutates its victim into a member of an old race.",al={"dagun hand powers","what does it do","poison hand"},sp=1}},ang={["faction:Alliance"]="For the Alliance, Gerrig Bonegrip's request offers a chance to help begin a new chapter of his order."},kw={"dagun","gerrig bonegrip","hand of dagun","legacy heart","poison","relic","star of xil'yeh","yagyin's digest"},rel={"npc:gerrig-bonegrip","quest:736","item:bonegrip-s-note","item:star-of-xil-yeh","item:the-legacy-heart","item:yagyin-s-digest","zone:ironforge"},src={"Wowpedia: Hand of Dagun","The Star, the Hand and the Heart (Alliance)"}}
E["item:large-stone-slab"] = {t="item",n="Large Stone Slab",z="badlands",s="Large Stone Slabs are pieces of rock elementals found in the Badlands. Lotwil Veriatus needs them for tests of his spells.",h="Large Stone Slabs are pieces of rock elementals found in the Badlands.",sec={{t="Stone for Study",b="West of Lotwil Veriatus in the Badlands, rock elementals carry the slabs he seeks. Their larger, stronger bodies yield pieces suited to his tests. Lotwil believes his spells can help him control elementals, and these stones are part of that work.",sp=0}},faq={{q="Where do Large Stone Slabs come from?",a="Rock elementals in the Badlands carry Large Stone Slabs. Lotwil Veriatus points to the hills west of him and along the nearby mountain edges.",al={"where slab from","stone slab source"}},{q="Who wants the slabs?",a="Lotwil Veriatus needs Large Stone Slabs for his tests of spells meant to control elementals.",al={"who needs slabs","lotwil stone"}},{q="Why does Lotwil want them?",a="Lotwil tests his spells on the slabs, hoping to use them in experiments to control elementals.",al={"why slabs","what are stones for"}},{q="Which elementals carry them?",a="Rock elementals carry the slabs Lotwil seeks. His directions place them west of him and along the mountain edges.",al={"what rock elemental","which stones"}}},ang={["race:Tauren"]="Lotwil marvels that a single tauren brought him the slabs, saying he expected it would take half a dozen."},kw={"badlands","elemental","large stone slab","lotwil veriatus","rock elemental","stone","stone slab"},rel={"quest:710","npc:lotwil-veriatus","zone:badlands","subzone:mirage-flats"},src={"Wowpedia: Large Stone Slab","Study of the Elements: Rock (2)"}}
E["item:lotwil-s-shackles-of-elemental-binding"] = {t="item",n="Lotwil's Shackles of Elemental Binding",z="badlands",s="Lotwil Veriatus made these shackles for a bold attempt to summon an elemental in the Badlands. Their recovery matters to his work.",h="Lotwil Veriatus made these shackles for a bold attempt to summon an elemental in the Badlands.",sec={{t="A Summoning Prepared",b="In the Badlands, Lotwil Veriatus has finished the shackles for a remarkable experiment. He calls on Lucien and Servo to witness his blend of alchemy, engineering, and arcane magic. With the binding ready, Lotwil means to summon a powerful elemental.",sp=0},{t="The Outcome",b="The Fam'retor Guardian leaves Lotwil's shackles behind. When you bring them back, he thanks you for the trouble and says his magic sent the creature home. Whatever went wrong, the shackles are returned to their maker.",sp=1}},faq={{q="What are Lotwil's Shackles of Elemental Binding?",a="They are shackles Lotwil Veriatus made for an attempt to bind a powerful elemental.",al={"lotwil's shackles","elemental binding shackles","what are the shackles"}},{q="Who made the shackles?",a="Lotwil Veriatus made them as part of an experiment blending alchemy, engineering, and arcane magic.",al={"who made these","lotwil shackles maker","who is lotwil"}},{q="Where can I find the shackles?",a="The Fam'retor Guardian in the Badlands leaves Lotwil's shackles behind.",al={"where shackles","shackles location","fam'retor guardian"},sp=1},{q="Why does Lotwil want the shackles back?",a="Lotwil needs them returned after his attempt to summon a powerful elemental goes awry.",al={"why return shackles","what does lotwil need","shackles for lotwil"},sp=1}},kw={"alchemy","badlands","elemental","engineering","fam'retor guardian","lotwil veriatus","lotwil's shackles","shackles of elemental binding"},rel={"npc:lotwil-veriatus","zone:badlands","quest:734"},src={"Wowpedia: Lotwil's Shackles of Elemental Binding","This Is Going to Be Hard (3)"}}
E["item:rock-elemental-shard"] = {t="item",n="Rock Elemental Shard",z="badlands",s="Rock Elemental Shards are fragments gathered from rock elementals in the Badlands. Jarkal Mossmeld needs them among several reagents to replenish his alchemical stocks.",h="Rock Elemental Shards are fragments gathered from rock elementals in the Badlands.",sec={{t="Stone Reagents",b="In Kargath, Jarkal Mossmeld asks for five Rock Elemental Shards alongside buzzard gizzards and crag coyote fangs. He is an alchemist seeking to replenish his stocks, and promises coin for the gathered reagents.",sp=0}},faq={{q="What are Rock Elemental Shards for?",a="Jarkal Mossmeld in Kargath needs five Rock Elemental Shards to replenish his alchemical stocks.",al={"shard use","why shards","what does jarkal need"}},{q="Where do Rock Elemental Shards come from?",a="Rock Elemental Shards come from rock elementals in the Badlands.",al={"shard source","where shards","get rock shards"}},{q="Who wants the shards?",a="Jarkal Mossmeld, an alchemist in Kargath, asks for five Rock Elemental Shards.",al={"who needs shards","jarkal shards","who is jarkal"}},{q="What else does Jarkal need?",a="Jarkal also asks for five buzzard gizzards and ten crag coyote fangs.",al={"other reagents","jarkal needs what","gizzards and fangs"}}},ang={["faction:Horde"]="As a member of the Horde, you can bring the Badlands reagents to Jarkal Mossmeld in Kargath, where he offers coin for them."},kw={"alchemical reagents","badlands","jarkal mossmeld","kargath","rock elemental shard","rock elementals"},rel={"quest:2258","zone:badlands","subzone:kargath","item:buzzard-gizzard","item:crag-coyote-fang"},src={"Wowpedia: Rock Elemental Shard","Badlands Reagent Run (Horde)"}}
E["item:ryedol-s-lucky-pick"] = {t="item",n="Ryedol's Lucky Pick",z="badlands",s="Ryedol’s Lucky Pick is a mining tool lost when Shadowforge dwarves attacked Hammertoe’s Digsite in the Badlands. Prospector Ryedol hopes to get it back.",h="Ryedol’s Lucky Pick is a mining tool lost when Shadowforge dwarves attacked Hammertoe’s Digsite in the...",sec={{t="A Prospector’s Tool",b="Prospector Ryedol works south of Hammertoe’s Digsite in the Badlands. The Shadowforge clan attacked the excavation site and killed nearly everyone there, including Ryedol’s boss, Hammertoe. Ryedol escaped, but his lucky pick was left behind. He asks you to search among the Dark Iron dwarves for the tool.",sp=0}},faq={{q="Who owns Ryedol’s Lucky Pick?",a="Prospector Ryedol owns the pick and wants it returned.",al={"ryedol pick","lucky pick owner"}},{q="Where was the pick lost?",a="The pick was left at Hammertoe’s Digsite in the Badlands after the Shadowforge clan attacked.",al={"where pick lost","pick location"}},{q="Who has Ryedol’s Lucky Pick?",a="One of the Shadowforge dwarves at Hammertoe’s Digsite has the pick.",al={"who has pick","shadowforge pick"}},{q="Why does Ryedol want the pick back?",a="It is Ryedol’s lucky pick, and he asks you to recover it from the Shadowforge dwarves.",al={"why lucky pick","ryedol needs pick"}}},ang={["race:Dwarf"]="As a dwarf, you can help Prospector Ryedol recover his tool after the Shadowforge attack on Hammertoe’s Digsite."},kw={"badlands","dark iron","hammertoe's digsite","lucky pick","prospector ryedol","ryedol's lucky pick","shadowforge"},rel={"quest:719","npc:prospector-ryedol","zone:badlands","topic:dwarf"},src={"Wowpedia: Ryedol's Lucky Pick","A Dwarf and His Tools"}}
E["item:scrap-metal-scrounging"] = {t="item",n="Scrap Metal",z="badlands",s="Scrap Metal is scavenged from the ogres of Dustbelch Grotto in the Badlands. Sigrun needs it to build defenses and supplies for a small camp.",h="Scrap Metal is scavenged from the ogres of Dustbelch Grotto in the Badlands.",sec={{t="For the Camp",b="Sigrun needs scrap metal for defenses and other necessities at the camp in the Badlands. The ogres at Dustbelch Grotto to the west carry it, and the camp has little to spare. Until word comes from Ironforge or the Explorers' League, every piece helps.",sp=0}},faq={{q="What is scrap metal for?",a="Sigrun needs scrap metal to construct defenses and other necessities for the camp in the Badlands.",al={"scrap metal use","why collect scrap","metal for sigrun"}},{q="Where can I find scrap metal?",a="The ogres at Dustbelch Grotto, west of Sigrun's camp in the Badlands, carry scrap metal.",al={"scrap metal location","where metal","dustbelch metal"}},{q="Who wants the scrap metal?",a="Sigrun wants scrap metal to help supply and defend the camp.",al={"who needs metal","sigrun scrap","metal for who"}},{q="Why is Sigrun gathering supplies?",a="Sigrun has few materials for the camp's defenses and other necessities, so he is gathering what he can.",al={"camp needs supplies","why scrounge","sigrun defenses"}}},ang={["race:Dwarf"]="As a dwarf, you may know the camp is waiting for word from Ironforge while Sigrun makes do with the supplies at hand.",["profession:Engineering"]="As an engineer, you can see why Sigrun needs scrap metal: the camp lacks materials for defenses and other necessities."},kw={"badlands","camp","dustbelch grotto","explorers' league","ironforge","ogres","scrap metal","scrounging","sigrun"},rel={"quest:733","zone:badlands","zone:ironforge","topic:explorers-league"},src={"Wowpedia: Scrap Metal (Scrounging)","Scrounging"}}
E["item:sealed-note-to-advisor-belgrum"] = {t="item",n="Sealed Note to Advisor Belgrum",z="badlands",s="Historian Karnik's sealed note carries a warning from the Badlands to Advisor Belgrum. Its contents guide the next step against the Shadowforge dwarves.",h="Historian Karnik's sealed note carries a warning from the Badlands to Advisor Belgrum.",sec={{t="A Warning Carried",b="In Ironforge, you carry Historian Karnik's note to Advisor Belgrum. Karnik asks you to tell Belgrum what you witnessed and seek his counsel. Meanwhile, Karnik turns to the spirit of Hammertoe, hoping it may help stop the Shadowforge dwarves' activities.",sp=0}},faq={{q="Who wrote the sealed note?",a="Historian Karnik sent the note to Advisor Belgrum.",al={"note writer","who sent the note"}},{q="Who is the note for?",a="The note is addressed to Advisor Belgrum.",al={"who gets it","note for belgrum"}},{q="What is the note about?",a="Karnik says the note will explain what you witnessed and asks Belgrum for guidance on how to proceed.",al={"what does it say","note contents"}},{q="Why is Karnik sending the note?",a="Karnik wants Belgrum to hear what you witnessed and decide how they should proceed.",al={"why carry it","karnik's message"}},{q="What is Karnik doing while you carry it?",a="Karnik plans to speak with Hammertoe's spirit, hoping it can help stop the Shadowforge dwarves' activities in the Badlands.",al={"what's karnik doing","hammertoe spirit"}}},kw={"advisor belgrum","badlands","hammertoe","historian karnik","passing word of a threat","sealed note","shadowforge"},rel={"quest:725","quest:720","quest:723","zone:badlands"},src={"Wowpedia: Sealed Note to Advisor Belgrum","Passing Word of a Threat"}}
E["item:sigil-of-the-hammer"] = {t="item",n="Sigil of the Hammer",z="badlands",s="The Sigil of the Hammer is a sign used to approach scholars who hold Yagyin’s Digest. It opens a path to knowledge sought for protection.",h="The Sigil of the Hammer is a sign used to approach scholars who hold Yagyin’s Digest.",sec={{t="A Sign of Learning",b="A tablet points toward a digest written by Yagyin, and the Sigil of the Hammer is the sign that opens the way to it. In Ironforge, Gerrig Bonegrip keeps a shop in the Forlorn Cavern. In the Undercity, Keeper Bel'dugur tends a collection of books. Show the sigil to either scholar and ask for the digest.",sp=0}},faq={{q="What is the Sigil of the Hammer for?",a="The Sigil of the Hammer identifies its bearer to scholars who can be asked for Yagyin's Digest.",al={"sigil use","hammer sigil purpose"}},{q="Who do I show the sigil to?",a="Show the Sigil of the Hammer to Gerrig Bonegrip in Ironforge or Keeper Bel'dugur in the Undercity.",al={"who gets the sigil","sigil recipient"}},{q="Where is Gerrig Bonegrip?",a="Gerrig Bonegrip keeps a shop in the Forlorn Cavern of Ironforge.",al={"gerrig location","gerrig shop"}},{q="Where is Keeper Bel'dugur?",a="Keeper Bel'dugur is in the Undercity, where he tends a collection of books.",al={"bel'dugur location","undercity scholar"}},{q="Why does the digest matter?",a="The digest holds knowledge sought to protect those who seek it.",al={"why yagyin digest","digest importance"}}},kw={"forlorn cavern","gerrig bonegrip","hammer sigil","ironforge","keeper bel'dugur","sigil of the hammer","undercity","yagyin's digest"},rel={"quest:727","quest:728","item:yagyin-s-digest","npc:gerrig-bonegrip","npc:keeper-bel-dugur","zone:ironforge","zone:undercity"},src={"Wowpedia: Sigil of the Hammer","To Ironforge for Yagyin's Digest","To the Undercity for Yagyin's Digest"}}
E["item:sign-of-the-earth"] = {t="item",n="Sign of the Earth",z="badlands",s="The Sign of the Earth is a Dark Iron-made seal sought in the Badlands. It holds the key to a prison in Lethlor Ravine.",h="The Sign of the Earth is a Dark Iron-made seal sought in the Badlands.",sec={{t="A Stolen Seal",b="Garek, sent to the Badlands by Krasus of the Kirin Tor, asks you to recover the Sign of the Earth. Wandering ogres took it and pass near Camp Boff. The mark was made by Dark Iron dwarves at Angor Fortress, and it binds two prisoners in Lethlor Ravine.",sp=0},{t="The Prison's Key",b="In Kargath, Gorn tells you that the Horde once allied with Deathwing during the Second War. Tho'grun and his ogres were hired to obtain the Sign, but Tho'grun betrayed the Horde and kept it. With the seal returned, Gorn means to open the drakes' prison and free them to their doom.",sp=1}},faq={{q="What is the Sign of the Earth?",a="The Sign of the Earth is a seal made by the Dark Iron dwarves at Angor Fortress. It binds Blacklash and Hematus in Lethlor Ravine.",al={"sign of earth","earth sign","what's the sign"}},{q="Who wants the Sign of the Earth?",a="Garek, sent by Krasus of the Kirin Tor, asks you to retrieve the Sign. Gorn in Kargath also seeks it for the Horde.",al={"who needs the sign","garek sign","gorn sign"}},{q="Who stole the Sign?",a="A band of wandering ogres took the Sign of the Earth. Their leader, Tho'grun, kept it after betraying the Horde.",al={"who has the sign","tho grun sign","ogres stole it"},sp=1},{q="What does the Sign unlock?",a="The Sign of the Earth is the key to the prison holding the black drakes Blacklash and Hematus in Lethlor Ravine.",al={"sign prison key","unlock what","black drakes prison"}},{q="Where can I find the Sign?",a="The wandering ogres sometimes travel through Camp Boff in the Badlands, where Tho'grun may be found.",al={"sign location","where sign earth","camp boff sign"}}},ang={["faction:Horde"]="As a member of the Horde, the Sign recalls the old alliance with Deathwing during the Second War. Gorn seeks it to free Blacklash and Hematus, though he means their doom.",["class:Mage"]="As a mage, you may recognize Krasus as a master of the Kirin Tor. He sent Garek to the Badlands to stop trouble brewing in Lethlor Ravine."},kw={"angor fortress","badlands","blacklash","deathwing","garek","gorn","hematus","lethlor ravine","sign of the earth","tho'grun"},rel={"quest:717","quest:782","zone:badlands","subzone:kargath","npc:deathwing","topic:horde"},src={"Wowpedia: Sign of the Earth","Tremors of the Earth","Broken Alliances (1)"}}
E["item:singed-scroll-fragment"] = {t="item",n="Singed Scroll Fragment",z="badlands",s="The Singed Scroll Fragment is one of three pieces of a destroyed scroll sought by Theldurin the Lost. Its recovery may help guard against Myzrael.",h="The Singed Scroll Fragment is one of three pieces of a destroyed scroll sought by Theldurin the Lost.",sec={{t="A Scorched Piece",b="Enraged Rock Elementals in the hills behind Theldurin the Lost carry the Singed Scroll Fragment. He seeks it with two other pieces of the Scroll of Myzrael, hoping the fragments can be joined again.",sp=0}},faq={{q="What is the Singed Scroll Fragment?",a="It is one of three fragments from the destroyed Scroll of Myzrael.",al={"singed fragment","singed scroll piece"}},{q="Where does the fragment come from?",a="Enraged Rock Elementals in the hills behind Theldurin the Lost carry it.",al={"where find singed fragment","singed fragment location"}},{q="Who wants the fragment?",a="Theldurin the Lost asks for it alongside the Torn Scroll Fragment and the Crumpled Scroll Fragment.",al={"who needs singed fragment","theldurin fragment"}},{q="Why does Theldurin want the fragments?",a="He hopes to reattach them so the Scroll of Myzrael can be used against Myzrael.",al={"why collect fragments","myzrael scroll why"}}},kw={"badlands","crumpled scroll fragment","enraged rock elemental","myzrael","scroll of myzrael","singed scroll fragment","theldurin the lost","torn scroll fragment"},rel={"quest:692","item:scroll-of-myzrael","item:crumpled-scroll-fragment","item:torn-scroll-fragment","npc:theldurin-the-lost","zone:badlands"},src={"Wowpedia: Singed Scroll Fragment","The Lost Fragments"}}
E["item:small-stone-shard"] = {t="item",n="Small Stone Shard",z="badlands",s="Small Stone Shards come from lesser rock elementals in the Badlands. Lotwil Veriatus needs them to test spells and devices for his elemental binding work.",h="Small Stone Shards come from lesser rock elementals in the Badlands.",sec={{t="Stone for Study",b="Lesser rock elementals in the hills west of Lotwil Veriatus carry Small Stone Shards. The mage gathers them for tests of his offensive spells and the devices he has assembled. He is working on shackles meant to bind elementals, and these shards are among the materials he needs.",sp=0}},faq={{q="Where do Small Stone Shards come from?",a="You take them from the lesser rock elementals that roam the hills west of Lotwil Veriatus.",al={"small shard source","stone shard where","lesser rock elementals"}},{q="Who wants the shards?",a="Lotwil Veriatus needs Small Stone Shards for his work on elemental binding and his tests of spells and devices.",al={"who needs shards","Lotwil shards","give shards to who"}},{q="What are the shards used for?",a="Lotwil Veriatus uses Small Stone Shards to test offensive spells and devices for his work on shackles of elemental binding.",al={"why shards","shard purpose","what Lotwil doing"}},{q="Where is Lotwil Veriatus working?",a="Lotwil Veriatus is working in the Badlands, with lesser rock elementals in the hills immediately to the west.",al={"Lotwil location","where is Lotwil","mage in badlands"}}},ang={["class:Mage"]="As a mage, you can see Lotwil Veriatus testing offensive spells and devices as he works on shackles for binding elementals."},kw={"badlands","elemental binding","lesser rock elemental","lotwil veriatus","offensive spells","shackles","small stone shard","small stone shards"},rel={"quest:710","npc:lotwil-veriatus","zone:badlands","topic:mage"},src={"Wowpedia: Small Stone Shard","Study of the Elements: Rock"}}
E["item:star-of-xil-yeh"] = {t="item",n="Star of Xil'yeh",z="badlands",s="The Star of Xil'yeh is a powerful gem said to let its holder speak with beings on other worlds. Gerrig Bonegrip seeks it among three relics in Ironforge.",h="The Star of Xil'yeh is a powerful gem said to let its holder speak with beings on other worlds.",sec={{t="A Relic Sought",b="In Ironforge, Gerrig Bonegrip asks for the Star of Xil'yeh as one of three relics he needs. He seeks the items to trade for Yagyin's Digest, a book tied to the beginning of a new chapter for his order.",sp=0}},faq={{q="What does the Star of Xil'yeh do?",a="The Star of Xil'yeh is said to let its holder speak with beings on other worlds.",al={"star of xil'yeh power","what is the star gem","xil'yeh gem"}},{q="Why does Gerrig Bonegrip want the Star?",a="Gerrig needs the Star of Xil'yeh alongside the Hand of Dagun and the Legacy Heart. He seeks the three relics in exchange for Yagyin's Digest.",al={"why gerrig wants star","bonegrip star","gerrig relics"}},{q="Where can the Star be found?",a="Grel'borg the Miser in the Alterac Mountains has the Star of Xil'yeh.",al={"star location","where is xil'yeh","find the star"}},{q="What is Yagyin's Digest?",a="Yagyin's Digest is a book Gerrig Bonegrip offers in exchange for three relics. He believes it may help begin a new chapter for his order.",al={"yagyin digest","why bonegrip wants digest","bonegrip book"}},{q="What are the other relics Gerrig seeks?",a="Along with the Star of Xil'yeh, Gerrig asks for the Hand of Dagun and the Legacy Heart.",al={"hand and heart","three relics","bonegrip items"}}},ang={["faction:Alliance"]="As an Alliance adventurer, you may carry this relic to Gerrig Bonegrip in Ironforge, where he seeks it for his order."},kw={"gem","gerrig bonegrip","hand of dagun","legacy heart","other worlds","star of xil'yeh","xil'yeh","yagyin's digest"},rel={"quest:736","npc:gerrig-bonegrip","item:yagyin-s-digest","item:hand-of-dagun","item:the-legacy-heart","zone:alterac","zone:ironforge"},src={"Wowpedia: Star of Xil'yeh","The Star, the Hand and the Heart (Alliance)"}}
E["item:supply-crate-blasted-lands"] = {t="item",n="Supply Crate",z="badlands",s="The Supply Crate is abandoned excavation gear sought by Sigrun Ironhew in the Badlands. Its contents could help his hungry company.",h="The Supply Crate is abandoned excavation gear sought by Sigrun Ironhew in the Badlands.",sec={{t="Left Behind",b="After leaving the Uldaman excavation site in haste, Sigrun Ironhew's company abandoned wagons and supply crates. Ogres from Camp Kosh seized their equipment, including a cart carrying weapons. The company has been left without food, and Sigrun asks you to recover a Supply Crate.",sp=0}},faq={{q="Who wants the Supply Crate?",a="Sigrun Ironhew wants you to retrieve the Supply Crate for his company in the Badlands.",al={"who needs the crate","sigrun crate"}},{q="Where was the Supply Crate left?",a="The crate was among the supplies abandoned when Sigrun Ironhew's company fled the Uldaman excavation site.",al={"crate location","where's the crate"}},{q="Why does Sigrun need the crate?",a="Sigrun's company lost its food supplies after ogres from Camp Kosh seized their equipment. He asks you to recover a Supply Crate.",al={"why crate","they need supplies"}},{q="What did the ogres take?",a="Ogres from Camp Kosh seized the company's abandoned equipment, including a cart carrying weapons.",al={"camp kosh ogres","what did ogres steal"}},{q="What happens when you return?",a="Sigrun thanks you, then says the company will go out to find food that night.",al={"crate completion","sigrun response"},sp=1}},kw={"badlands","camp kosh","excavation","food","mirages","sigrun ironhew","supply crate","uldu-man"},rel={"quest:718","zone:badlands","subzone:camp-kosh","subzone:uldaman","quest:733"},src={"Wowpedia: Supply Crate (Blasted Lands)","Mirages"}}
E["item:the-legacy-heart"] = {t="item",n="The Legacy Heart",z="badlands",s="Dark magic clings to the Legacy Heart, a relic sought alongside two other items of power. Gerrig Bonegrip in Ironforge wants it for a purpose tied to Yagyin's Digest.",h="Dark magic clings to the Legacy Heart, a relic sought alongside two other items of power.",sec={{t="A Relic of Power",b="Gerrig Bonegrip asks for the Legacy Heart among three relics he has written on Bonegrip's Note. He will trade the digest for them, but keeps their names from spoken ears. The Heart's dark enchantment has earned it a fearsome reputation.",sp=0}},faq={{q="What is the Legacy Heart?",a="The Legacy Heart is a relic of power sought by Gerrig Bonegrip in exchange for Yagyin's Digest.",al={"legacy heart","heart relic","dark magic heart"}},{q="Who wants the Legacy Heart?",a="Gerrig Bonegrip in Ironforge asks for the Legacy Heart and two other relics.",al={"who wants the heart","gerrig heart","bonegrip relic"}},{q="Why does Gerrig want it?",a="Gerrig needs the Legacy Heart with two other relics before he will give up Yagyin's Digest.",al={"why bonegrip wants it","heart purpose","gerrig's reason"}},{q="What is the Heart said to do?",a="Dark magic is said to grant the Legacy Heart's holder immortality; its current owner bears the title the Undying.",al={"heart power","legacy heart magic","never die heart"},sp=2},{q="What other relics does Gerrig seek?",a="Gerrig asks for the Star of Xil'yeh, the Hand of Dagun and the Legacy Heart.",al={"other relics","star hand heart","bonegrip's list"}}},ang={["faction:Alliance"]="As an Alliance traveler, you can bring the Legacy Heart and two other relics to Gerrig Bonegrip in Ironforge in exchange for Yagyin's Digest."},kw={"bonegrip's note","dark magic","gerrig bonegrip","hand of dagun","legacy heart","star of xil'yeh","yagyin's digest"},rel={"npc:gerrig-bonegrip","quest:736","item:bonegrip-s-note","item:hand-of-dagun","item:star-of-xil-yeh","item:yagyin-s-digest","zone:badlands","zone:stranglethorn"},src={"Wowpedia: The Legacy Heart","The Star, the Hand and the Heart (Alliance)"}}
E["item:torn-scroll-fragment"] = {t="item",n="Torn Scroll Fragment",z="badlands",s="A Torn Scroll Fragment is one piece of the Scroll of Myzrael, sought by Theldurin the Lost in the Badlands. He fears Myzrael may be free, and believes the scroll could help contain her.",h="A Torn Scroll Fragment is one piece of the Scroll of Myzrael, sought by Theldurin the Lost in the Badlands.",sec={{t="A Lost Piece",b="Theldurin the Lost needs the Torn Scroll Fragment along with two other pieces to mend the Scroll of Myzrael. Enraged Rock Elementals in the hills behind him carry the fragments, which they tore from the destroyed scroll and now fight over. Theldurin hopes the repaired scroll can help contain Myzrael.",sp=0}},faq={{q="What is the Torn Scroll Fragment?",a="The Torn Scroll Fragment is one of three pieces of the destroyed Scroll of Myzrael. Theldurin the Lost is trying to gather them so he can mend the scroll.",al={"torn fragment","scroll piece","torn scroll bit"}},{q="Who wants this fragment?",a="Theldurin the Lost wants the Torn Scroll Fragment, along with the Crumpled Scroll Fragment and Singed Scroll Fragment.",al={"who needs torn fragment","theldurin fragment","give fragment to who"}},{q="Where did the scroll fragments come from?",a="Enraged elementals stole the Scroll of Myzrael and tore it into pieces. They now fight over the fragments.",al={"why fragments","who tore scroll","scroll destroyed"}},{q="Why does Theldurin need the Scroll of Myzrael?",a="Theldurin fears Myzrael may be free and gathering strength. He believes the Scroll of Myzrael may be needed to trap her again.",al={"why theldurin wants scroll","myzrael scroll purpose","trap myzrael"}},{q="Which elementals carry the fragments?",a="Enraged Rock Elementals in the hills behind Theldurin carry the scroll fragments.",al={"where torn fragment","what elemental drops it","badlands scroll pieces"}}},kw={"badlands","enraged rock elemental","myzrael","scroll fragments","scroll of myzrael","theldurin the lost","torn scroll fragment"},rel={"quest:692","item:scroll-of-myzrael","npc:theldurin-the-lost","item:crumpled-scroll-fragment","item:singed-scroll-fragment","zone:badlands"},src={"Wowpedia: Torn Scroll Fragment","The Lost Fragments"}}
E["item:yagyin-s-digest"] = {t="item",n="Yagyin's Digest",z="badlands",s="Yagyin’s Digest is a book you carry back to Theldurin in the Badlands. He believes its truths may help save those threatened by what lies beneath the earth.",h="Yagyin’s Digest is a book you carry back to Theldurin in the Badlands.",sec={{t="A Dangerous Book",b="Gerrig Bonegrip hands over Yagyin’s Digest for you to take to Theldurin. Gerrig warns that its truths can burn and asks you to keep it from unfriendly hands. The book matters to those who fear what may rise from below.",sp=0}},faq={{q="What is Yagyin’s Digest?",a="Yagyin’s Digest is a book Gerrig Bonegrip entrusts to you for Theldurin. Gerrig says it holds many truths and warns that the truth can burn.",al={"yagyin digest","what's the digest","the book"}},{q="Who is Theldurin?",a="Theldurin the Lost is the dwarf in the Badlands who sends you after Yagyin’s Digest and waits for you to bring it back.",al={"who wants the book","theldurin guy","who do I bring it to"}},{q="Why is the digest dangerous?",a="Gerrig Bonegrip warns that the truths in Yagyin’s Digest can burn. He does not want it to reach unfriendly hands.",al={"why dangerous","truth can burn","what's in the book"}},{q="What might the book help prevent?",a="Theldurin hopes your efforts may help save those threatened if the beings below are freed and rise to the surface.",al={"what are they afraid of","worm food","what's under the ground"}}},kw={"badlands","book","digest","forbidden knowledge","theldurin","truth","yagyin","yagyin's digest"},rel={"quest:737","zone:badlands"},src={"Wowpedia: Yagyin's Digest","Forbidden Knowledge (Classic)"}}
E["npc:deathwing"] = {t="npc",n="Deathwing",z="badlands",s="Deathwing's shadow still reaches Azeroth's deepest places. Once Neltharion the Earth-Warder, he was the black dragonflight's Dragon Aspect until the Old Gods drove him mad. He turned against the other Aspects and brought fire and turmoil to the world. Defeated near grim batol after the Second War, he is believed slain or hidden away.",h="Deathwing's shadow still reaches Azeroth's deepest places.",sec={{t="The Fall of Neltharion",b="The titans gave Neltharion dominion over the earth and Azeroth's subterranean vaults. In those depths, the imprisoned Old Gods whispered to him. During the ancient War of the Ancients, their madness took hold. Neltharion tricked the other Dragon Aspects into placing part of their essence in a golden disc called the Dragon Soul. He said it would stop the Burning Legion, then turned the weapon on his allies and unleashed devastation.",sp=0},{t="Scheme of the Human Lord",b="After the Second War, Deathwing plotted to bring down mortal kingdoms from within. Taking the human identity of Lord Daval Prestor, a charming noble, he won the favor of King Terenas Menethil II and the high council of the Alliance of Lordaeron.\n\nHe aimed to claim Alterac's vacant throne. At grim batol, he also helped the Dragonmaw clan keep Queen Alexstrasza enslaved and harvest her clutches. Rhonin destroyed the Demon Soul and restored the other Aspects' stolen power. They drove Deathwing away.",sp=1},{t="The Brood Left Behind",b="Most mortal kingdoms believe Deathwing was destroyed or driven from the world for good. The black dragonflight remains a scourge across Azeroth, led by his cunning brood, including his daughter Onyxia and son nefarian. Black drakes manipulate mortal politics and terrorize the land from mountain lairs. The scars of the black Aspect's ancient treachery run deep. Travelers crossing craggy wastelands or descending into deep tunnels still fear the Great Dragon may stir.",sp=0}},faq={{q="Who was Deathwing originally?",a="Deathwing was once Neltharion the Earth-Warder, leader of the black dragonflight. The titans empowered him to shepherd Azeroth's land and mountains. Millennia ago, the deep earth exposed him to the Old Gods' whispers, which eroded his sanity.",al={"neltharion history","who is neltharion","earth warder origin"}},{q="What was the Dragon Soul?",a="The Dragon Soul was a golden artifact Neltharion forged during the War of the Ancients. He tricked the other four Aspects into pouring their power into it, then turned its apocalyptic force against them and mortal defenders. It later became known as the Demon Soul.",al={"demon soul","what is the dragon soul","neltharion's artifact"}},{q="Who was Lord Daval Prestor?",a="Lord Daval Prestor was the human identity Deathwing adopted after the Second War. Using charm magic and courtly deception, he tried to claim Alterac's throne and manipulate the Alliance of Lordaeron from within before his treachery came to light.",al={"lord prestor","daval prestor identity","prestor lore"},sp=1},{q="What is Deathwing's connection to Grim Batol?",a="At Grim Batol, Deathwing secretly gave the Dragonmaw orcs the Demon Soul, keeping the red dragon queen Alexstrasza chained and bred for war. Rhonin later destroyed the artifact with one of Deathwing's scales. Restored to their power, the other Aspects fought Deathwing and drove him away.",al={"deathwing grim batol","what happened at grim batol"}},{q="Who leads the black dragonflight today?",a="With Deathwing absent and presumed dead, his chief descendants act on their own. His daughter Onyxia broods in her lair in Dustwallow Marsh, while his son Nefarian commands black dragons and experiments with dragonsblood high atop Blackrock Mountain.",al={"current black dragon leader","who leads black dragons","nefarian and onyxia"},sp=2}},ang={["faction:Alliance"]="Alliance nobles still shudder at how close Lord Daval Prestor came to taking Alterac's crown and turning the Council of Seven Nations against the Alliance from within.",["faction:Horde"]="The Old Horde made a wicked bargain with Deathwing during the Second War, using the Dragonmaw clan to secure red dragons. The new Horde seeks to leave that stain in the past.",["race:NightElf"]="As a Night Elf, you know that Kaldorei elders remember Neltharion's sudden, devastating betrayal ten thousand years ago during the War of the Ancients. The atrocity broke dragonkind and sealed the doom of their ancient empire."},kw={"aspect","black dragonflight","deathwing","demon soul","destroyer","dragon soul","earth-warder","grim batol","neltharion","prestor"},rel={"topic:black-dragonflight","topic:war-of-the-ancients","subzone:grim-batol","topic:old-god","topic:alliance-of-lordaeron","topic:old-horde","topic:second-war"},src={"Deathwing"}}
E["npc:lotwil-veriatus"] = {t="npc",n="Lotwil Veriatus",z="badlands",s="East of Kargath, Lotwil Veriatus pursues dangerous experiments with the Badlands' elementals. The gnomish scholar works with his sarcastic apprentice Lucien Tosselwrench and mechanical attendant Servo, hoping to unite arcane theory, alchemy, and engineering.",h="East of Kargath, Lotwil Veriatus pursues dangerous experiments with the Badlands' elementals.",sec={{t="A Unified Field of Chaos",b="From Kharanos in Dun Morogh, Lotwil dreams of founding a grand University for his Enlightened Assembly of Arcanology, Alchemy, and Engineering Sciences. He believes arcane study, alchemy, and engineering belong together, not in separate pursuits. So he came to the harsh Badlands to study its native rock elementals and make shackles that bind elemental forces.\n\nLotwil has studied elemental machines and defeated dark iron constructs. Yet his mind stays so fixed on the work that he often misses the explosive danger of his experiments.",sp=0},{t="The Elemental Shackles",b="In the Badlands, Lotwil puts his shackles of elemental binding to the test. He sends adventurers to gather rock elemental cores, coolant, and gyrochronatoms for a ritual to subdue an elemental servant. When he activates the device, volatile magic, erratic engineering, and unstable alchemical reagents meet in disaster. A towering, enraged elemental monstrosity named Fam'retor appears and turns on its creator.",sp=1}},faq={{q="Who is Lotwil Veriatus?",a="Lotwil Veriatus is a gnomish scholar at an isolated camp east of Kargath in the Badlands. A founding member of the Enlightened Assembly of Arcanology, Alchemy, and Engineering Sciences, he seeks to unite all three fields in one discipline.",al={"who is lotwil","lotwil veriatus lore","gnome in badlands"}},{q="Why is Lotwil out in the Badlands?",a="Lotwil came to the Badlands to study its many wild rock elementals. The open desert gives him raw elemental material and room for volatile binding experiments away from major population centers.",al={"why is lotwil in badlands","lotwil badlands camp","what is lotwil doing"}},{q="Who is Lucien Tosselwrench?",a="Lucien Tosselwrench is Lotwil's gnomish assistant. Cynical and weary of his master's eccentric ramblings, he handles logistics, repairs Servo, and warns bystanders about Lotwil's dangerous carelessness.",al={"lucien tosselwrench","lotwil assistant","lotwil apprentice"}},{q="What happens when Lotwil finishes his experiment?",a="Lotwil tries to enslave an elemental construct with his custom shackles of elemental binding. The device fails spectacularly and summons Fam'retor, an enormous, enraged rock elemental that must be slain before it destroys Lotwil's camp.",al={"lotwil experiment fail","shackles of elemental binding","fam'retor"},sp=1}},ang={["race:Gnome"]="As a gnome, you can see intellectual ambition pushed to reckless extremes in Lotwil's attempt to unite engineering and the arcane, whatever the risks.",["profession:Engineering"]="As an engineer, you may recognize Lotwil's effort to join mechanical gyros and gears with arcane containment fields. His work shows how suddenly engineering can fail with violent force."},kw={"badlands","elemental","fam'retor","kargath","lotwil","lucien","servo","veriatus"},rel={"zone:badlands","subzone:kargath","subzone:kharanos","topic:gnome","topic:goblin","topic:third-war"},src={"Lotwil Veriatus"}}
E["npc:prospector-ryedol"] = {t="npc",n="Prospector Ryedol",z="badlands",s="South of Hammertoe's Digsite, Prospector Ryedol watches over the Explorers' League's work in the Badlands. He searches for dwarven relics and keeps hope alive amid troggs and beasts.",h="South of Hammertoe's Digsite, Prospector Ryedol watches over the Explorers' League's work in the Badlands.",sec={{t="Watching Over the Digs",b="From a hill south of Hammertoe's Digsite, Prospector Ryedol directs the Explorers' League's work. The dry valley holds ancient titan secrets and traces of dwarven heritage, yet troggs, coyotes, and drakes threaten the expeditions. Dark Iron dwarves have stolen dwarven gear, so Ryedol sends out efforts to recover it. The League has lost much in these wastes, and he searches ruined outposts for signs of hope.",sp=0}},faq={{q="Who is Prospector Ryedol?",a="Ryedol is a dwarven field researcher for the Explorers' League. His camp sits on a high hill overlooking Hammertoe's Digsite in the eastern Badlands, where he directs salvage and recovery work.",al={"ryedol","who is ryedol","prospector ryedol location"}},{q="What is Ryedol doing in the Badlands?",a="Ryedol supports the Explorers' League's archaeological work in the Badlands. Dark Iron dwarves and troggs have overrun or compromised nearby digsites, so he works with travelers to recover relics, find lost tools, and learn what happened to his fellow dwarves.",al={"what is ryedol doing","ryedol's mission","why is ryedol here"}},{q="What is Ryedol's Hammer?",a="Ryedol's Hammer is given for recovering his Lucky Pick from the Dark Iron dwarves who attacked Hammertoe's Digsite. The stolen item is his pick, not the hammer.",al={"ryedol hammer","dwarf and his tools"}}},ang={["race:Dwarf"]="As a dwarf, you see Ryedol carry Ironforge's drive to uncover the origins of your people, even in Khaz Modan's harshest reaches.",["faction:Alliance"]="As an Alliance traveler crossing the Badlands, you find a friendly face in Ryedol and urgent work supporting the Explorers' League."},kw={"badlands","digsite","explorers' league","hammertoe","ironforge","prospector ryedol","ryedol"},rel={"zone:badlands","topic:explorers-league","topic:dwarf"},src={"Prospector Ryedol"}}
E["npc:theldurin-the-lost"] = {t="npc",n="Theldurin the Lost",z="badlands",s="Theldurin the Lost wanders the Badlands alone, wary and half-mad. He fled the Twilight's Hammer with sacred relics after learning what the cult intended.",h="Theldurin the Lost wanders the Badlands alone, wary and half-mad.",sec={{t="A Mind Fractured by Darkness",b="Theldurin wanders the barren hills of the Badlands with bags of explosives, gripped by wild paranoia. He once belonged to the Twilight's Hammer. When the cult sought to awaken a primordial elemental power trapped beneath the earth, he recoiled in terror.\n\nHe rejected its teachings and fled into the desert. He carried the Scroll of Myzrael, hoping to keep his former masters from unleashing an ancient horror upon the world. His escape cost him his sanity, but his defiance dealt a serious blow to the cult's plans.",sp=0},{t="A Desperate Countermeasure",b="Enraged earth elementals ambushed Theldurin in the wastes and tore apart his stolen scroll, scattering the fragments across the dust. Paranoia besieges him, and visions haunt him of doom sleeping beneath the surface. The crazed dwarf seeks ancient texts, the Tablet of Ryun'eh and Yagyin's Digest, to uncover long-buried lore. He plans to force Myzrael's premature summoning so she can be defeated and bound again.",sp=1}},faq={{q="Who is Theldurin the Lost?",a="Theldurin is a half-mad dwarven hermit wandering the Badlands. Once a member of the Twilight's Hammer, he stole the Scroll of Myzrael and fled into the wilderness to stop the cult from unleashing a dangerous power.",al={"who is theldurin","theldurin lore","mad dwarf badlands"}},{q="Why is Theldurin hiding in the Badlands?",a="Theldurin fled to the Badlands after stealing the Scroll of Myzrael from the Twilight's Hammer. He hides in its remote, sun-baked canyons, away from the cultists hunting him.",al={"why is theldurin here","why does theldurin hide","theldurin badlands"}},{q="What is the Scroll of Myzrael?",a="The Scroll of Myzrael is an arcane parchment holding the ritual knowledge needed to release Myzrael, an ancient, corrupted elemental entity trapped deep beneath Arathi. Theldurin stole it to keep the Twilight's Hammer from completing the summoning, but local elementals later shredded it into pieces.",al={"scroll of myzrael","what scroll did theldurin steal"},sp=1},{q="What does Theldurin want to do with Myzrael?",a="The bindings on Myzrael are weakening, and Theldurin wants to summon her before she gathers her full strength. He hopes she can then be banished and sealed beneath the crust again before the Twilight's Hammer can master her power.",al={"theldurin plan","why summon myzrael","summoning the princess"},sp=1}},ang={["race:Dwarf"]="Seeing a fellow son of Ironforge reduced to raving paranoia in a wasteland is tragic. Yet Theldurin's refusal to bow to dark cults shows the stubbornness dwarves are known for.",["profession:Engineering"]="Theldurin threatens approaching strangers with a pack brimming with blastpowder, relying on volatile explosives in an unpredictable way."},kw={"badlands","blastpowder","myzrael","ryun'eh","scroll of myzrael","theldurin","theldurin the lost","twilight's hammer"},rel={"topic:twilight-s-hammer","zone:badlands","topic:dwarf","topic:old-god","zone:ironforge","zone:undercity"},src={"Theldurin the Lost"}}
E["npc:warlord-goretooth"] = {t="npc",n="Warlord Goretooth",z="badlands",s="At Kargath, Warlord Goretooth directs the Horde's frontier campaigns. From his tower, he watches the Dark Iron dwarves and the danger of Blackrock Mountain. At times, he leaves his lookout to relax by the campfire.",h="At Kargath, Warlord Goretooth directs the Horde's frontier campaigns.",sec={{t="Commander of Kargath",b="Warlord Goretooth directs Horde operations from Kargath's watchtower. The outpost is Orgrimmar's main staging ground against dangers in Blackrock Mountain and the ravines around it. Goretooth oversees patrols and coordinates scouts such as the Kargath Expeditionary Force. He also orders attacks on the Dark Iron clan's ranks and leaders.\n\nAway from his lookout, the stern commander sometimes warms himself by the campfire. There, he trades quips with the Forsaken casters before returning to duty.",sp=0},{t="Striking the Dark Irons",b="Warlord Goretooth sees the Dark Iron dwarves as a direct threat to Horde interests in the Eastern Kingdoms. He favors attacks over defense and plans strikes against General Angerforge and Emperor Dagran Thaurissan's forces in Blackrock Depths. Assaulting an ancient stronghold beneath the earth is no small undertaking.\n\nBefore approving another push into the mountain, Goretooth often seeks counsel from veteran orcs such as Eitrigg in Orgrimmar.",sp=0}},faq={{q="Who is Warlord Goretooth?",a="Warlord Goretooth commands the Horde forces stationed at Kargath in the Badlands. He organizes patrols and directs attacks against the Dark Iron dwarves.",al={"warlord goretooth","who is goretooth","goretooth badlands","kargath commander"}},{q="What is his role in Kargath?",a="Warlord Goretooth commands Kargath and sends the Kargath Expeditionary Force into the field. He orders operations against the Dark Iron clan in Blackrock Depths.",al={"what does goretooth do","goretooth duties","goretooth post"}},{q="Why is Goretooth sending soldiers against Blackrock Depths?",a="The Dark Iron dwarves threaten the surrounding regions and oppose the Horde's presence. Goretooth orders attacks on their soldiers, senior officers, and General Angerforge to weaken their hold on the mountain.",al={"why kill dark irons","death to angerforge quest","goretooth dark iron"}},{q="Why does Goretooth consult Eitrigg?",a="Eitrigg is a veteran orc who lived inside Blackrock Mountain and knows its politics and defenses. Goretooth seeks his counsel before escalating attacks on Blackrock strongholds.",al={"goretooth and eitrigg","eitriggs wisdom","why talk to eitrigg"}}},ang={["faction:Horde"]="As a member of the Horde, you can see how Warlord Goretooth directs its operations against the Dark Iron dwarves from Kargath.",["class:Warrior"]="As a warrior, you can face the seasoned dwarven legionnaires targeted by Goretooth's direct military orders."},kw={"angerforge","badlands","blackrock","dark iron","eitrigg","goretooth","kargath","warlord goretooth"},rel={"subzone:kargath","zone:badlands","npc:eitrigg","topic:horde"},src={"Warlord Goretooth"}}
E["quest:1108"] = {t="quest",n="Indurium",z="badlands",s="In the Badlands, Martek the Exiled seeks metal samples for Fizzle's car. Indurium is said to endure heat and stress, and Stonevault troggs sometimes carry flakes.",h="In the Badlands, Martek the Exiled seeks metal samples for Fizzle's car.",sec={{t="A Metal Worth Testing",b="Martek the Exiled stays in the Badlands for more than solitude. He thinks indurium might suit Fizzle's car because it is said to endure heat and stress. He wants samples for a test, with the forge ready.",sp=0},{t="Flakes from the Troggs",b="True indurium ore lies deep in Uldaman, but Stonevault troggs in the Badlands sometimes carry flakes. Martek asks for ten. The troggs roam the south-east slope of a rocky clump at Agmond's End, just south of the Valley of Fangs.",sp=0},{t="The Forge Test",b="Martek heats the flakes in his forge, raising the heat in stages. They hold firm, and he swears by Orgrim that indurium can withstand massive heat. The test succeeds. Martek calls the metal amazing stuff.",sp=1}},faq={{q="Who sends you after the indurium?",a="Martek the Exiled, in the central Badlands, asks for indurium samples. The chain to him begins with Fizzle Brassbolts at the Mirage Raceway in Thousand Needles.",al={"who gives indurium quest","where to get indurium"}},{q="Why does Martek need indurium?",a="Martek thinks indurium might suit Fizzle's car because it is said to endure heat and stress. He wants samples to test in his forge.",al={"what is indurium used for","why indurium"}},{q="Where can the indurium flakes be found?",a="Stonevault troggs in the Badlands sometimes carry indurium flakes. They roam the south-east slope of a rocky clump at Agmond's End, just south of the Valley of Fangs.",al={"where are indurium flakes","how to get flakes","who drops indurium flakes"}},{q="Where does true indurium ore come from?",a="Martek says true indurium ore lies deep in Uldaman.",al={"where is indurium ore","where is indurium mined"}},{q="What comes before this?",a="Martek the Exiled comes first in the chain, which begins with Fizzle Brassbolts at the Mirage Raceway.",al={"previous quest indurium","how to start indurium"}},{q="What comes after the flakes are delivered?",a="The chain continues with News for Fizzle.",al={"next quest after indurium","what happens next"}}},kw={"agmond's end","badlands","fizzle brassbolts","indurium","indurium flakes","martek the exiled","mirage raceway","stonevault troggs","uldaman"},rel={"quest:1106","quest:1137","npc:fizzle-brassbolts","zone:badlands","subzone:agmond-s-end","subzone:uldaman","topic:trogg"},m={start="Martek the Exiled",["end"]="Martek the Exiled",level="39",faction="Neutral",id=1108},src={"Indurium"}}
E["quest:1137"] = {t="quest",n="News for Fizzle",z="badlands",s="In the Badlands, Martek the Exiled has news for Fizzle Brassbolts about indurium. You carry his message to the Mirage Raceway on the Shimmering Flats in Thousand Needles.",h="In the Badlands, Martek the Exiled has news for Fizzle Brassbolts about indurium.",sec={{t="Martek's Word on Indurium",b="Martek says indurium withstands heat remarkably well, so it may suit Fizzle's pistons. Flakes will not do; Fizzle needs real indurium ore, dug from deep within Uldaman at the Badlands' northern edge. Martek names Uldaman as indurium's true source. He sends his regards and asks you to repeat all he has told you to Fizzle Brassbolts.",sp=0},{t="Fizzle Hears the News",b="Fizzle Brassbolts is eager to hear Martek's words and learn whether he can help. When you tell Fizzle of your travels in the Badlands, he declares indurium the key.",sp=1}},faq={{q="Where does this journey begin and end?",a="Martek the Exiled in the Badlands gives you a message for Fizzle Brassbolts at the Mirage Raceway on the Shimmering Flats in Thousand Needles.",al={"who gives news for fizzle","where to turn in news for fizzle","martek to fizzle"}},{q="What news does Martek send to Fizzle?",a="Martek says indurium withstands heat remarkably well and may suit Fizzle's pistons. Fizzle needs real ore, not flakes, mined from deep within Uldaman.",al={"what does martek say","indurium news","martek message"}},{q="Where does indurium ore come from?",a="Martek says indurium ore is dug from deep within Uldaman at the northern edge of the Badlands. He calls Uldaman indurium's true source.",al={"where is indurium ore","indurium ore source"}},{q="Where in the storyline does this step fit?",a="This follows Indurium in the chain that began when Fizzle Brassbolts sent you to Martek the Exiled.",al={"news for fizzle chain","previous quest news for fizzle"}}},kw={"badlands","fizzle brassbolts","indurium","indurium ore","martek the exiled","mirage raceway","shimmering flats","thousand needles","uldaman"},rel={"npc:fizzle-brassbolts","quest:1108","quest:1106","subzone:mirage-raceway","subzone:shimmering-flats","subzone:uldaman"},m={start="Martek the Exiled",["end"]="Fizzle Brassbolts",level="38",faction="Neutral",id=1137},src={"News for Fizzle"}}
E["quest:1419"] = {t="quest",n="Coyote Thieves",z="badlands",s="In Kargath, crag coyotes have stolen food, and Neeka Bloodscar wants them hunted. She asks you to bring back thirty jawbones.",h="In Kargath, crag coyotes have stolen food, and Neeka Bloodscar wants them hunted.",sec={{t="Thieves of Kargath",b="Neeka Bloodscar asks whether you have spent many days in the Badlands, felt its heat, and met the beasts of its dusty plains. Crag coyotes are tough, and they have crept into Kargath to steal food from the outpost. She wants you to hunt them and bring back their jawbones. Bring enough, and Neeka may believe you know the Badlands.",sp=0}},faq={{q="Why does Neeka Bloodscar want coyote jawbones?",a="Crag coyotes have crept into Kargath and stolen food from the outpost. Neeka wants them hunted, and their jawbones will show that you know the Badlands.",al={"why coyote jawbones","neeka bloodscar motivation","why collect jawbones"}},{q="Where are the coyotes causing trouble?",a="Crag coyotes wander the Badlands' dusty plains and have crept into Kargath to steal food.",al={"coyote location","where to find crag coyotes","where are the coyotes"}},{q="How many jawbones does Neeka Bloodscar want?",a="Neeka Bloodscar wants you to bring her thirty coyote jawbones in Kargath.",al={"how many jawbones","coyote jawbone count"}},{q="Who is Neeka Bloodscar?",a="Neeka Bloodscar is at the Kargath outpost in the Badlands. She asks you to hunt crag coyotes.",al={"who is neeka","neeka bloodscar"}}},kw={"badlands","coyote thieves","crag coyote","jawbones","kargath","neeka bloodscar"},rel={"subzone:kargath","zone:badlands"},m={start="Neeka Bloodscar",["end"]="Neeka Bloodscar",level="40",faction="Horde",id=1419,ri={"Coyote Jawbone"}},src={"Coyote Thieves"}}
E["quest:1420"] = {t="quest",n="Report to Helgrum",z="badlands",s="At Kargath, Neeka Bloodscar gives you a fresh report for Helgrum the Swift in Stonard. You have just spoken with her there.",h="At Kargath, Neeka Bloodscar gives you a fresh report for Helgrum the Swift in Stonard.",sec={{t="A Report for Stonard",b="Neeka Bloodscar gives you a fresh report for Helgrum in Stonard. She warns that anyone who calls themselves an outrunner must keep the way and avoid falling to an enemy.",sp=0},{t="Helgrum Reads the Report",b="Helgrum the Swift reads Neeka's report and learns that the Alliance has troubles of its own. He thinks the Horde and Alliance may share some enemies.",sp=1}},faq={{q="Who sends you with the report?",a="Neeka Bloodscar has written a fresh report for Helgrum and asks you to carry it.",al={"who gives report to helgrum","quest giver report to helgrum","who starts this quest"}},{q="Where does the report need to be delivered?",a="Deliver the report to Helgrum the Swift in Stonard.",al={"where to turn in report to helgrum","helgrum location","where is helgrum"}},{q="What comes before this?",a="This follows your earlier visit to Neeka Bloodscar at Kargath.",al={"previous quest","prerequisite for report to helgrum","what quest comes first"}}},kw={"badlands","helgrum the swift","horde intelligence","neeka bloodscar","outrunner","report","stonard"},rel={"quest:1418","subzone:stonard","zone:badlands","topic:alliance"},m={start="Neeka Bloodscar",["end"]="Helgrum the Swift",level="40",faction="Horde",id=1420},src={"Report to Helgrum"}}
E["quest:2202"] = {t="quest",n="Uldaman Reagent Run",z="badlands",s="In Kargath, Jarkal Mossmeld seeks freshly discovered magenta fungus caps that sprout deep within Uldaman. He hopes to unravel their alchemical uses, though harvesting them means braving hazardous spores.",h="In Kargath, Jarkal Mossmeld seeks freshly discovered magenta fungus caps that sprout deep within Uldaman.",sec={{t="Spores in the Deep",b="Gathering the specimens carries real danger, for disturbing the clusters can trigger a burst of venomous spores. Once gathered, Jarkal Mossmeld expects a dozen caps brought back to Kargath, where he plans to test their alchemical value and brew restorative draughts.",sp=0}},faq={{q="Who is asking for the fungus caps?",a="Jarkal Mossmeld is an alchemist stationed in Kargath who wants to study newly discovered flora.",al={"who is jarkal mossmeld","who wants the fungus caps","jarkal in kargath"}},{q="Where are the magenta fungus caps found?",a="They grow in clusters deep inside the ancient dig site of Uldaman.",al={"where do magenta fungus caps grow","magenta cap location","where to find fungus in uldaman"}},{q="Why does Jarkal want the fungus?",a="He wants to examine their properties and investigate how they might serve in alchemy.",al={"why does jarkal want magenta fungus","what are magenta caps used for","magenta fungus purpose"}},{q="Is collecting the fungus dangerous?",a="The clusters can release poisonous spores when disturbed or jostled.",al={"is picking magenta caps dangerous","poison spores magenta caps","spore danger uldaman"}},{q="What does Jarkal offer in return?",a="He promises a batch of his greater mender's potion once you bring him a dozen caps.",al={"what is the reward for jarkal","greater menders potion","jarkal mossmeld potion"}}},kw={"alchemy","jarkal mossmeld","kargath","magenta fungus caps","poison spores","reagent run","uldaman"},rel={"subzone:kargath","subzone:uldaman"},m={faction="Horde",id=2202},src={"In-game quest text: Uldaman Reagent Run"},fv=true}
E["quest:2258"] = {t="quest",n="Badlands Reagent Run",z="badlands",s="In Kargath, Jarkal Mossmeld needs Badlands reagents to refill his stocks. He offers coin when you bring them to him.",h="In Kargath, Jarkal Mossmeld needs Badlands reagents to refill his stocks.",sec={{t="Stocking the Shelves",b="Jarkal Mossmeld needs gizzards from five buzzards, fangs from ten crag coyotes, and shards from five rock elementals. Take each from the creatures themselves. If you do not fight, find friends who do. Jarkal pays in coin when you bring him the reagents.",sp=0},{t="After the Haul",b="Jarkal is pleased with what you bring and says it should last a little while. Yet he needs more reagents from deep inside the Uldaman excavation, where gathering them will be difficult. He hints that the pay may be worth more than shiny coins.",sp=1}},faq={{q="Who is asking for these reagents?",a="Jarkal Mossmeld, an alchemist of some note in Kargath, needs reagents to replenish his stocks.",al={"who gives badlands reagent run","jarkal mossmeld","who is jarkal mossmeld"}},{q="What ingredients does Jarkal need?",a="Jarkal needs gizzards from five buzzards, fangs from ten crag coyotes, and shards from five rock elementals. Take them from the creatures themselves.",al={"what items needed","badlands reagents list","reagents required"}},{q="Where is Jarkal Mossmeld located?",a="Jarkal Mossmeld is in the outpost of Kargath, in the Badlands.",al={"jarkal mossmeld location","where is kargath alchemist","where to turn in badlands reagent run"}},{q="What does Jarkal offer in exchange for the ingredients?",a="Jarkal offers coin when you bring the reagents to him in Kargath. He pays nothing before then.",al={"badlands reagent run reward","what do i get"}}},kw={"alchemy","badlands","buzzard gizzard","crag coyote fang","jarkal mossmeld","kargath","rock elemental shard","uldaman"},rel={"subzone:kargath","zone:badlands","subzone:uldaman"},m={start="Jarkal Mossmeld",["end"]="Jarkal Mossmeld",level="39",faction="Horde",id=2258,ri={"Buzzard Gizzard","Crag Coyote Fang","Rock Elemental Shard"}},src={"Badlands Reagent Run (Horde)"}}
E["quest:2338"] = {t="quest",n="Translating the Journal",z="badlands",s="Jarkal offers to translate the journal if you let him borrow the necklace. He expects the bargain to benefit you both while Droffers and Son Salvage get what they want.",h="Jarkal offers to translate the journal if you let him borrow the necklace.",sec={{t="A Bargain",b="Jarkal wants to borrow the necklace in exchange for translating the journal. He believes you and he will each gain what you seek, while Droffers and Son Salvage will also think they have gained their wishes.",sp=0}},faq={{q="What does Jarkal want?",a="Jarkal asks to borrow the necklace and offers to translate the journal in exchange.",al={"jarkal necklace","what does he want","journal translation"}},{q="What is the deal?",a="You let Jarkal borrow the necklace, and he translates the journal for you.",al={"what's the bargain","necklace for translation","translate journal quest"}},{q="Who is Droffers and Son Salvage?",a="Droffers and Son Salvage are named in Jarkal's description of the bargain; he says they will think they are getting what they want.",al={"droffers and son","droffers salvage","who are droffers"}},{q="What does Jarkal think will happen?",a="Jarkal thinks you and he will each get what you want, and Droffers and Son Salvage will think the same.",al={"what does jarkal think","who gets what","deal outcome"}}},kw={"bargain","droffers","jarkal","journal","necklace","son salvage","translation"},m={faction="Horde",id=2338},src={"In-game quest text: Translating the Journal"},fv=true}
E["quest:2418"] = {t="quest",n="Power Stones",z="badlands",s="Rigglefuzz in the Badlands asks you to bring him Dentrium and An'Alleum Power Stones. You are to gather eight of each.",h="Rigglefuzz in the Badlands asks you to bring him Dentrium and An'Alleum Power Stones.",sec={{t="Rigglefuzz's Request",b="Rigglefuzz asks you for two kinds of power stone in the Badlands. He needs eight Dentrium Power Stones and eight An'Alleum Power Stones. Both kinds are needed for his request.",sp=0}},faq={{q="Who wants the power stones?",a="Rigglefuzz in the Badlands asks you to bring him the power stones.",al={"who asks for stones","Rigglefuzz stones"}},{q="Which power stones does Rigglefuzz need?",a="He needs Dentrium Power Stones and An'Alleum Power Stones.",al={"what stones","stone types"}},{q="How many Dentrium Power Stones are needed?",a="Rigglefuzz asks for eight Dentrium Power Stones.",al={"Dentrium amount","how many Dentrium"}},{q="How many An'Alleum Power Stones are needed?",a="Rigglefuzz asks for eight An'Alleum Power Stones.",al={"An'Alleum amount","how many An'Alleum"}}},kw={"an'alleum power stones","badlands","dentrium power stones","power stones","rigglefuzz"},rel={"zone:badlands"},m={id=2418},src={"In-game quest text: Power Stones"},fv=true}
E["quest:3821"] = {t="quest",n="Dreadmaul Rock",z="badlands",s="In the Burning Steppes, Sha'ni's platoon has been gone for more than three weeks. Thal'trak Proudtusk cannot leave his post, and asks you to learn what became of his wife.",h="In the Burning Steppes, Sha'ni's platoon has been gone for more than three weeks.",sec={{t="A Husband Without Word",b="Sha'ni went to the Burning Steppes to investigate strange rituals among the Firegut ogres. More than three weeks have passed, and Goretooth has heard nothing from her platoon. He tells Thal'trak to put the matter behind him and keep to his duty. But Sha'ni is his wife, and Thal'trak will not accept that. Bound to his post, he asks you to search for her.",sp=0},{t="Sha'ni's Words",b="Sha'ni speaks of Thal'trak with pity. They had planned to live with her mother and father in the Hinterlands once their tours were over. Now those plans are ruined.",sp=1}},faq={{q="Who is Thal'trak looking for?",a="Thal'trak is looking for his wife, Sha'ni Proudtusk. She was sent to the Burning Steppes to investigate strange rituals among the Firegut ogres, and no one has heard from her.",al={"who is missing","thaltrak wife","sha'ni proudtusk"}},{q="Why did Sha'ni go to the Burning Steppes?",a="Sha'ni was sent to the Burning Steppes more than three weeks ago to investigate reports of strange rituals among the Firegut ogres.",al={"shani mission","firegut ogre ritual","why did shani leave"}},{q="Why hasn't Thal'trak searched for her himself?",a="Thal'trak cannot leave his post, so he asks you to search for Sha'ni in his place.",al={"why cant thaltrak go","why is thaltrak waiting"}},{q="What does Goretooth say about the missing platoon?",a="Goretooth has heard nothing from anyone in Sha'ni's platoon. He advises Thal'trak to put the matter behind him and keep to his duty.",al={"goretooth response","what does goretooth say"}}},kw={"badlands","burning steppes","dreadmaul rock","firegut ogres","goretooth","sha'ni proudtusk","thal'trak proudtusk"},rel={"zone:burningsteppes","subzone:dreadmaul-rock","zone:badlands","zone:hinterlands"},m={start="Thal'trak Proudtusk",["end"]="Sha'ni Proudtusk",level="52",faction="Horde",id=3821},src={"Dreadmaul Rock (quest)"}}
E["quest:3906"] = {t="quest",n="Disharmony of Flame",z="badlands",s="Thunderheart sends you to the quarry in Blackrock Mountain to slay Overmaster Pyron. Return to Thunderheart when the assignment is complete.",h="Thunderheart sends you to the quarry in Blackrock Mountain to slay Overmaster Pyron.",sec={{t="At the Quarry",b="The quarry in Blackrock Mountain is where Thunderheart sends you. Overmaster Pyron is your target, and Thunderheart awaits your return after the assignment is complete.",sp=0}},faq={{q="Who is Thunderheart asking me to kill?",a="Thunderheart sends you to slay Overmaster Pyron at the quarry in Blackrock Mountain.",al={"who do I slay","pyron assignment","overmaster pyron"}},{q="Where is Overmaster Pyron?",a="Overmaster Pyron is at the quarry in Blackrock Mountain.",al={"where's pyron","quarry location","blackrock mountain target"}},{q="Who do I return to afterward?",a="Return to Thunderheart when you have completed the assignment.",al={"where do I go back","return to thunderheart","who waits for me"}}},kw={"blackrock mountain","disharmony of flame","flame","overmaster pyron","quarry","thunderheart"},rel={"subzone:blackrock-mountain"},m={faction="Horde",id=3906},src={"In-game quest text: Disharmony of Flame"},fv=true}
E["quest:4061"] = {t="quest",n="The Rise of the Machines",z="badlands",s="Hierophant Theodora Mulvadania asks you to recover Fractured Elemental Shards in the Burning Steppes. Golems and elementals there may yield what she needs.",h="Hierophant Theodora Mulvadania asks you to recover Fractured Elemental Shards in the Burning Steppes.",sec={{t="Theodora's Need",b="Theodora mentions the region's golems and elementals as a source of Fractured Elemental Shards. You are to seek those shards in the Burning Steppes and bring them to the Hierophant.",sp=0}},faq={{q="Who wants the shards?",a="Hierophant Theodora Mulvadania asks you to recover Fractured Elemental Shards for her.",al={"who needs shards","Theodora shards","shard giver"}},{q="Where are the Fractured Elemental Shards?",a="The shards are sought in the Burning Steppes, where Theodora recalls golems and elementals as their source.",al={"where shards","shard location","Burning Steppes shards"}},{q="What does Theodora need?",a="Theodora needs Fractured Elemental Shards.",al={"what shards","Theodora needs what","fractured shards"}},{q="What creatures are a source of the shards?",a="Theodora recalls that golems and elementals in the Burning Steppes are a source of the shards.",al={"shards from what","golems elementals","elemental shards"}}},kw={"burning steppes","elementals","fractured elemental shards","golems","the rise of the machines","theodora mulvadania"},rel={"zone:burningsteppes"},m={faction="Horde",id=4061},src={"In-game quest text: The Rise of the Machines"},fv=true}
E["quest:4062"] = {t="quest",n="The Rise of the Machines",z="badlands",s="In the Burning Steppes, the machines bore marks that now send you to Lotwil Veriatus.",h="In the Burning Steppes, the machines bore marks that now send you to Lotwil Veriatus.",sec={{t="Marks on the Shards",b="The shards bear G.L.A., with a rank marking beneath. The machines you brought down in the Burning Steppes bore Rank IV, which Theodora takes to be a low rank. So Hierophant Theodora Mulvadania sends you with a sample shard to Lotwil Veriatus, renowned among scholars of elemental sciences. Lotwil is stationed at a camp to the east, where Theodora hopes he can help with the search.",sp=0},{t="What Lotwil Sees",b="Lotwil Veriatus turns white when you show him the shard. He knows the markings.",sp=1}},faq={{q="Who sends you to Lotwil Veriatus?",a="Hierophant Theodora Mulvadania sends you with a sample shard from the machines destroyed in the Burning Steppes for Lotwil to inspect.",al={"who gives this quest","quest giver","theodora mulvadania"}},{q="Where is Lotwil Veriatus located?",a="Lotwil Veriatus is stationed at a camp to the east.",al={"where is lotwil","lotwil location","lotwil veriatus camp"}},{q="What markings are on the elemental shards?",a="The shards bear G.L.A., with a rank marking beneath. The destroyed machines bore Rank IV.",al={"shard initials","what does gla mean","rank iv"}},{q="Why does Theodora want Lotwil to inspect the shard?",a="Lotwil is renowned among scholars of elemental sciences, and Theodora hopes he can help with the search.",al={"why lotwil","why consult lotwil"}}},kw={"badlands","burning steppes","elemental shard sample","g.l.a.","lotwil veriatus","rise of the machines","theodora mulvadania"},rel={"npc:lotwil-veriatus","zone:badlands","zone:burningsteppes"},m={start="Hierophant Theodora Mulvadania",["end"]="Lotwil Veriatus",level="54",faction="Horde",id=4062},src={"The Rise of the Machines (2)"}}
E["quest:656"] = {t="quest",n="Summoning the Princess",z="badlands",s="At the Shards of Myzrael, you summon Myzrael and face her before she grows strong enough to challenge her captors. Theldurin the Lost wants her defeated and her Eldritch Shackles bound to the Shards.",h="At the Shards of Myzrael, you summon Myzrael and face her before she grows strong enough to challenge her...",sec={{t="Why She Must Be Stopped",b="Theldurin fears Myzrael will grow strong enough to turn against her captors. Some say she can be controlled. But Theldurin asks why the giants would have chained her if that were true.",sp=0},{t="At the Shards",b="You take the Scroll of Myzrael to the Shards, where you first spoke with her, and call her forth. Once Myzrael is defeated, you bind her Eldritch Shackles to the Shards and trap her again.",sp=0},{t="When the Shackles Are Placed",b="As Myzrael's shackles settle around the Shards, a wail rises from far below, then a roar. The Shards no longer offer warmth or safety. They pulse with menace, as though the thing beneath them bears ill will toward the surface.",sp=1}},faq={{q="Who sends you to fight Myzrael?",a="Theldurin the Lost sends you to defeat Myzrael before her strength grows enough to challenge her captors.",al={"quest giver","who gives summoning the princess","theldurin quest"}},{q="Where does the summoning take place?",a="You summon Myzrael at the Shards of Myzrael, where you first spoke with her.",al={"where to summon myzrael","shards of myzrael location","summoning spot"}},{q="Why does Theldurin want Myzrael defeated?",a="Theldurin fears Myzrael will grow strong enough to challenge her captors. He asks why the giants chained her if she could truly be controlled.",al={"why kill myzrael","theldurin motivation","why summon her"}},{q="How is Myzrael summoned?",a="You summon Myzrael at the Shards of Myzrael with the Scroll of Myzrael.",al={"how to summon her","scroll of myzrael use","summoning process"}},{q="What do you do with the Eldritch Shackles?",a="After defeating Myzrael, you bind her Eldritch Shackles to the Shards and trap her again.",al={"what item do i need","eldritch shackles","shackles of myzrael"}}},kw={"arathi highlands","eldritch shackles","myzrael","scroll of myzrael","shards of myzrael","theldurin the lost"},rel={"npc:theldurin-the-lost","zone:arathi"},m={start="Theldurin the Lost",["end"]="Shards of Myzrael",level="50",id=656,ri={"Eldritch Shackles"}},src={"Summoning the Princess"}}
E["quest:692"] = {t="quest",n="The Lost Fragments",z="badlands",s="Behind Theldurin, furious elementals fight over scraps of the Scroll of Myzrael. You gather the torn pieces while he fears what its magic might do.",h="Behind Theldurin, furious elementals fight over scraps of the Scroll of Myzrael.",sec={{t="A Dangerous Parchment",b="Theldurin the Lost fears the Scroll of Myzrael could draw Myzrael up to the surface. Then he considers another danger. She may already be free, or gathering strength to strike. If so, the scroll may be what you need to bind her again.",sp=0},{t="Torn by the Elements",b="Furious elementals took the scroll and tore it apart. Now they fight over its scraps in the hills behind Theldurin. Bring back three pieces: one torn, one crumpled and one singed. Theldurin hopes to mend them.",sp=0}},faq={{q="Who sends you to collect the scroll fragments?",a="Theldurin the Lost asks you to bring back pieces of the destroyed scroll.",al={"quest giver","who starts the lost fragments","theldurin quest"}},{q="What is the Scroll of Myzrael supposed to do?",a="Theldurin says the scroll’s magic could draw Myzrael up to the surface. If she is already free, he thinks it may be what you need to bind her again.",al={"what does the scroll do","scroll of myzrael lore","why find scroll fragments"}},{q="Where are the scroll fragments?",a="Furious elementals took the scroll, tore it apart and now fight over the scraps in the hills behind Theldurin.",al={"who has the fragments","where to find the scroll pieces","scroll fragment location"}},{q="What comes before this quest?",a="It follows your earlier dealings with Theldurin the Lost.",al={"previous quest","prerequisite for the lost fragments"}}},kw={"badlands","crumpled scroll fragment","elementals","myzrael","scroll of myzrael","singed scroll fragment","theldurin the lost","torn scroll fragment"},rel={"npc:theldurin-the-lost","quest:687","quest:656","zone:badlands"},m={start="Theldurin the Lost",["end"]="Theldurin the Lost",level="41",id=692,ri={"Crumpled Scroll Fragment","Singed Scroll Fragment","Torn Scroll Fragment"}},src={"The Lost Fragments"}}
E["quest:703"] = {t="quest",n="Barbecued Buzzard Wings",z="badlands",s="Rigglefuzz has every ingredient for his barbecued buzzard wings except the wings themselves.",h="Rigglefuzz has every ingredient for his barbecued buzzard wings except the wings themselves.",sec={{t="A Local Favorite",b="Rigglefuzz takes pride in his barbecued buzzard wings. He coats the tangy meat in rich sauce, and its aroma carries to hungry folk nearby. He has all the ingredients for a batch but the wings. Bring him four buzzard wings, and he may share the recipe.",sp=0}},faq={{q="Who asks for the buzzard wings?",a="Rigglefuzz wants buzzard wings for a batch of his barbecued wings.",al={"who gives barbecued buzzard wings","who is rigglefuzz","quest giver"}},{q="What does Rigglefuzz offer in return for the wings?",a="Rigglefuzz may share the recipe in return for enough wings.",al={"what is the reward","what do i get","recipe reward"}},{q="Why does Rigglefuzz need buzzard wings?",a="Rigglefuzz has every ingredient for the dish except the wings.",al={"why buzzards","rigglefuzz motive","why does rigglefuzz want wings"}},{q="How many wings does Rigglefuzz want?",a="Rigglefuzz wants four buzzard wings.",al={"how many buzzard wings","buzzard wing count"}}},ang={["profession:Cooking"]="Cooks can learn the recipe for the dish from Rigglefuzz."},kw={"badlands","barbecue","buzzard","cooking","recipe","rigglefuzz","wings"},rel={"zone:badlands"},m={start="Rigglefuzz",["end"]="Rigglefuzz",level="40",id=703},src={"Barbecued Buzzard Wings"}}
E["quest:705"] = {t="quest",n="Pearl Diving",z="badlands",s="In the Badlands, Rigglefuzz is running low on powder for his flash bombs. He sends you to the Vile Reef in Stranglethorn to gather more.",h="In the Badlands, Rigglefuzz is running low on powder for his flash bombs.",sec={{t="A Tricky Little Goblin",b="Rigglefuzz admits the Badlands frighten him. A short little goblin, he faces predators and scavengers all around. He knows how to make flash bombs, and uses them to drive the wildlife away. Now he is running low on crushed blue pearl powder.",sp=0},{t="Pearls from the Reef",b="Clams at the Vile Reef in Stranglethorn hold blue pearls. Rigglefuzz jokes that you had better wear good boots, then waits in the Badlands for nine pearls. He promises to make your effort worthwhile.",sp=0}},faq={{q="Why does Rigglefuzz need blue pearls?",a="Rigglefuzz uses crushed blue pearl powder to make flash bombs, and his supply is running low.",al={"rigglefuzz pearls","why pearl diving","why blue pearls"}},{q="Where are the blue pearls found?",a="Blue pearls are found in clams at the Vile Reef in Stranglethorn.",al={"where are blue pearls","blue pearl location","vile reef pearls"}},{q="Why does Rigglefuzz use flash bombs?",a="Vicious predators and bold scavengers fill the Badlands, so Rigglefuzz uses flash bombs to frighten the wildlife away.",al={"why flash bombs","rigglefuzz defense"}},{q="How many blue pearls does Rigglefuzz want?",a="Rigglefuzz wants you to bring him nine blue pearls in the Badlands.",al={"blue pearl count","how many pearls"}}},ang={["profession:Engineering"]="As an engineer, you have good reason to take an interest in Rigglefuzz's flash bombs."},kw={"badlands","blue pearl","flash bomb","pearl diving","rigglefuzz","stranglethorn vale","vile reef"},rel={"zone:badlands","subzone:vile-reef","zone:stranglethorn","topic:goblin"},m={start="Rigglefuzz",["end"]="Rigglefuzz",level="37",id=705},src={"Pearl Diving"}}
E["quest:706"] = {t="quest",n="Fiery Blaze Enchantments",z="badlands",s="A rare black drake whelp's still-beating heart is needed for Fiery Blaze Enchantments in the Badlands. Sigrun Ironhew waits for word from Ironforge, and the whelps of Lethlor Ravine may supply what she needs.",h="A rare black drake whelp's still-beating heart is needed for Fiery Blaze Enchantments in the Badlands.",sec={{t="An Apprentice's Craft",b="Sigrun Ironhew learned to kindle fire on weapons while apprenticed to Feranor Steeltoe. Feranor was last heard of among the smiths of a hunting party in Lordaeron. Sigrun waits in the Badlands for word from Ironforge. She has little else to do.",sp=0},{t="The Whelps of Lethlor Ravine",b="Sigrun shares little about the process. It calls for blood from the still-beating heart of a rare black drake whelp. Bring her a heart from a whelp in Lethlor Ravine, and she will show you the skill. The Scalding Whelps and Scorched Guardians there yield the hearts.",sp=0}},faq={{q="Who taught Sigrun Ironhew this enchantment technique?",a="Sigrun learned the technique as an apprentice to Feranor Steeltoe. Feranor was last heard of among the smiths of a hunting party in Lordaeron.",al={"sigrun teacher","who trained sigrun","feranor steeltoe"}},{q="What component is needed to place fire upon a blade?",a="The enchantment calls for blood from the still-beating heart of a rare black drake whelp.",al={"what does sigrun need","black drake heart requirement","fiery blaze materials"}},{q="Where are the black drake whelps found?",a="Black drake whelps are found in Lethlor Ravine, in the eastern Badlands.",al={"where to find black drakes","lethlor ravine whelps","black drake heart location"}},{q="Why is Sigrun Ironhew lingering in the Badlands?",a="Sigrun is waiting for word from Ironforge and has little else to do in the meantime.",al={"why is sigrun in badlands","sigrun ironhew purpose"}},{q="Which creatures yield the needed heart?",a="The Scalding Whelps and Scorched Guardians of Lethlor Ravine yield the needed heart.",al={"what drops black drakes heart","which whelps have hearts"}}},ang={["faction:Alliance"]="Sigrun Ironhew waits for word from Ironforge, and this work is meant for the Alliance."},kw={"badlands","black drake heart","feranor steeltoe","fiery blaze","ironforge","lethlor ravine","scalding whelp","scorched guardian","sigrun ironhew"},rel={"subzone:lethlor-ravine","zone:badlands","zone:ironforge","topic:lordaeron"},m={start="Sigrun Ironhew",["end"]="Sigrun Ironhew",level="45",faction="Alliance",id=706,ri={"Black Drake's Heart"}},src={"Fiery Blaze Enchantments"}}
E["quest:708"] = {t="quest",n="The Black Box",z="badlands",s="A giant condor in the Badlands swallowed a black box marked for Ironforge.",h="A giant condor in the Badlands swallowed a black box marked for Ironforge.",sec={{t="Pulled from a Condor",b="After ages in the condor's stomach, acid had pitted the metal. A symbol marks the underside above the words Engine #19 - Ironforge Siege Brigade. You carry the box to Pilot Longbeard in Ironforge's Hall of Arms.",sp=0}},faq={{q="Where did the corroded black box come from?",a="A giant condor in the Badlands swallowed the box, and it seems to have lain in its stomach for ages.",al={"where did the box come from","how did the box get here","black box origin"}},{q="What markings are stamped on the box?",a="A symbol is stamped on the underside above the words Engine #19 - Ironforge Siege Brigade.",al={"what does the box say","markings on the black box","box inscription"}},{q="Who is supposed to receive the box?",a="Pilot Longbeard, in the Hall of Arms in Ironforge.",al={"who gets the box","where does the black box go","who do i bring the box to"}}},ang={["faction:Alliance"]="The box bears Ironforge's mark, and its trail leads to Ironforge."},kw={"badlands","black box","corroded black box","giant condor","hall of arms","ironforge siege brigade","pilot longbeard"},rel={"npc:pilot-longbeard","zone:ironforge","zone:badlands"},m={start="Corroded Black Box",["end"]="Pilot Longbeard",level="40",faction="Alliance",id=708},src={"The Black Box"}}
E["quest:710"] = {t="quest",n="Study of the Elements: Rock",z="badlands",s="In the Badlands, Lotwil Veriatus needs stone shards to test his work on elemental shackles. Lesser rock elementals roam the hills just west of him.",h="In the Badlands, Lotwil Veriatus needs stone shards to test his work on elemental shackles.",sec={{t="Elemental Shackles",b="In the Badlands, Lotwil Veriatus is making shackles of elemental binding. When finished, they will let mages summon stronger elementals for greater uses. To test his offensive spells and a few pieced-together gizmos, he needs ten small stone shards. Lesser rock elementals roam the hills immediately west.",sp=0}},faq={{q="Who is asking for the stone shards?",a="Lotwil Veriatus is asking for stone shards as he works in the Badlands.",al={"who gives this quest","quest giver","lotwil veriatus"}},{q="What is Lotwil Veriatus working on?",a="Lotwil Veriatus is making shackles of elemental binding. They will let mages summon stronger elementals.",al={"lotwil project","shackles of elemental binding","what is lotwil building"}},{q="Why does Lotwil need small stone shards?",a="Lotwil needs the shards to test offensive spells and a few pieced-together gizmos.",al={"why stone shards","shards purpose","what are shards for"}},{q="Where are the stone shards found?",a="The shards come from lesser rock elementals in the hills immediately west of Lotwil.",al={"where to find shards","lesser rock elementals location","stone shard source"}}},ang={["class:Mage"]="As a mage, you are among those Lotwil's shackles are meant to serve."},kw={"badlands","lesser rock elementals","lotwil veriatus","shackles of elemental binding","small stone shards","study of the elements: rock"},rel={"npc:lotwil-veriatus","zone:badlands","topic:mage"},m={start="Lotwil Veriatus",["end"]="Lotwil Veriatus",level="37",faction="Neutral",id=710,ri={"Small Stone Shard"}},src={"Study of the Elements: Rock"}}
E["quest:711"] = {t="quest",n="Study of the Elements: Rock",z="badlands",s="Lotwil Veriatus is ready to test larger pieces after the small shards behaved as he expected. He needs three large stone slabs from rock elementals.",h="Lotwil Veriatus is ready to test larger pieces after the small shards behaved as he expected.",sec={{t="Bigger Pieces",b="Lotwil Veriatus needs sturdier pieces for his next tests. Rock elementals have larger bodies, so their remains may yield slabs big enough.\n\nHe points you farther west or southeast along the mountain edges to gather three large stone slabs. For now, Lotwil needs time to test the smaller pieces you brought.",sp=0},{t="Lotwil's Hopes",b="Lotwil's spells acted on the smaller pieces as he predicted. If the next experiment goes as he expects, the elementals he controls will outshine anything he has summoned before.",sp=0}},faq={{q="Who sends you after the large slabs?",a="Lotwil Veriatus, working in the Badlands, sends you to gather the large slabs.",al={"who gives this quest","lotwil quest","study of the elements giver"}},{q="What came before this request?",a="Before this request, you brought Lotwil small stone shards during the earlier Study of the Elements: Rock.",al={"previous quest","prior step","what did i do before"}},{q="Where does Lotwil say to find the rock elementals?",a="Lotwil points you farther west or southeast along the edges of the mountains.",al={"where are the elementals","elemental locations","where to find slabs"}},{q="Why does Lotwil need larger stone slabs?",a="Lotwil needs larger pieces for his next tests. Rock elementals have bigger, stronger bodies, so their remains may yield pieces large enough.",al={"why large slabs","purpose of slabs","lotwil research goal"}}},kw={"badlands","large stone slabs","lotwil veriatus","rock elementals","stone slabs","study of the elements: rock"},rel={"npc:lotwil-veriatus","quest:710","zone:badlands","subzone:mirage-flats"},m={start="Lotwil Veriatus",["end"]="Lotwil Veriatus",level="39",faction="Neutral",id=711,ri={"Large Stone Slab"}},src={"Study of the Elements: Rock (2)"}}
E["quest:712"] = {t="quest",n="Study of the Elements: Rock",z="badlands",s="In the Badlands, Lotwil Veriatus needs bracers from greater rock elementals to judge his shackles.",h="In the Badlands, Lotwil Veriatus needs bracers from greater rock elementals to judge his shackles.",sec={{t="Gauging the Shackles",b="Lotwil Veriatus needs one last part from the Badlands' elementals, after the stone slabs. Bracers of rock binding from greater rock elementals will help him judge the shackles under construction.\n\nHis scrying found a group southwest, near some ogres, if memory serves. He asks for five bracers so there will be spares, since Servo often misplaces reagents and research.",sp=0}},faq={{q="Why does Lotwil need the bracers?",a="Bracers of rock binding will let Lotwil gauge the strength of his own shackles.",al={"why bracers of rock binding","what are bracers for","lotwil binding bracers"}},{q="Why does Lotwil ask for five bracers?",a="Lotwil asks for five bracers so there are extras, since Servo often misplaces reagents and research.",al={"why five bracers","how many bracers","why extras"}},{q="Where are the greater rock elementals located?",a="Lotwil's scrying found a group southwest, near some ogres. The hills around Camp Cagg are home to the greater rock elementals.",al={"where are rock elementals","greater rock elemental location","where to find bracers"}},{q="What becomes of the stone slabs collected earlier?",a="When the work here is done, Lucien will take the extra slabs back to Kharanos, where they could prove useful again.",al={"what happened to stone slabs","lucien stone slabs","kharanos slabs"}}},kw={"badlands","bracers of rock binding","greater rock elementals","kharanos","lotwil veriatus","lucien","ogres","servo"},rel={"npc:lotwil-veriatus","zone:badlands","subzone:kharanos"},m={start="Lotwil Veriatus",["end"]="Lotwil Veriatus",level="42",faction="Neutral",id=712,ri={"Bracers of Rock Binding"}},src={"Study of the Elements: Rock (3)"}}
E["quest:713"] = {t="quest",n="Coolant Heads Prevail",z="badlands",s="Lotwil Veriatus needs Frost Oil for the shackles holding his summoned friend. Bro'kin, Lotwil's goblin friend in Alterac, can teach you to make it.",h="Lotwil Veriatus needs Frost Oil for the shackles holding his summoned friend.",sec={{t="A Vital Coolant",b="Lotwil Veriatus says Frost Oil keeps engines and gears from overheating. He calls it an unmatched lubricant. It also helps magical items hold their enchantments. The oil could strengthen Lotwil's shackles enough to stop his summoned friend from killing everyone.",sp=0},{t="Bro'kin of Alterac",b="Bro'kin, Lotwil's goblin friend, can teach you to make Frost Oil. He sells from a spot on the old city's wall in the Ruins of Alterac.",sp=0},{t="When the Oil Arrives",b="When the oil arrives, Lotwil calls it the perfect coolant for the new bracers. He swears that if the enchantments do not last a century, all his belongings will go to Servo. Lotwil expects the mages of the Assembly to be in awe when the work is finished.",sp=1}},faq={{q="Why does Lotwil Veriatus need Frost Oil?",a="Frost Oil would strengthen Lotwil Veriatus's shackles enough to stop his summoned friend from killing everyone.",al={"why frost oil","what is frost oil for","lotwil oil"}},{q="Who knows how to brew Frost Oil?",a="Bro'kin, Lotwil Veriatus's goblin friend, can teach you to make Frost Oil. He sells from a spot on the old city's wall in the Ruins of Alterac.",al={"who teaches frost oil","where to learn frost oil","brokin recipe"}},{q="What is special about Frost Oil?",a="Lotwil Veriatus says Frost Oil keeps engines and gears from overheating. He calls it an unmatched lubricant, and says it helps magical items hold their enchantments.",al={"frost oil properties","why is frost oil good"}}},kw={"badlands","bro'kin","coolant heads prevail","frost oil","lotwil veriatus","ruins of alterac","shackles"},rel={"npc:lotwil-veriatus","zone:badlands","subzone:ruins-of-alterac","topic:goblin"},m={start="Lotwil Veriatus",["end"]="Lotwil Veriatus",level="37",faction="Neutral",id=713},src={"Coolant Heads Prevail"}}
E["quest:714"] = {t="quest",n="Gyro... What?",z="badlands",s="In the Badlands, Lotwil Veriatus is still at work on his contraption. You have brought him the Frost Oil from Coolant Heads Prevail, but one small part is missing: a gyrochronatom.",h="In the Badlands, Lotwil Veriatus is still at work on his contraption.",sec={{t="A Crucial Part",b="Lotwil Veriatus is so caught up in his work that he praises you for doing the job beyond all standards. Then he says you may apply for work if you meet him in Kharanos.\n\nA hurried scramble follows as Lotwil tries to catch hold of something. Then he asks for a gyrochronatom. The part is small but crucial, and with it the project should be ready to complete.",sp=0},{t="Handing It Over",b="Lotwil Veriatus seizes the gyrochronatom with a shout when you hand it over. The work is nearly done, he says, and the project is his top priority. His promise to finish soon stretches from a few minutes to perhaps much longer.",sp=1}},faq={{q="Who is asking for the gyrochronatom?",a="Lotwil Veriatus is working on a contraption in the Badlands and asks you for a gyrochronatom.",al={"who gives gyro what","gyro what quest giver","lotwil veriatus badlands"}},{q="What does Lotwil Veriatus need the gyrochronatom for?",a="The gyrochronatom is a small but crucial part of Lotwil Veriatus's project. With it, he should be ready to complete the work.",al={"why gyrochronatom","what is lotwil building"}},{q="What is the offer about Kharanos?",a="Lotwil Veriatus says you may apply for work if you meet him in Kharanos.",al={"lotwil kharanos","kharanos job offer"}},{q="Where can a gyrochronatom be found?",a="Engineers make gyrochronatoms, and engineering suppliers sell them.",al={"how to get gyrochronatom","gyrochronatom source","where buy gyrochronatom"}}},ang={["profession:Engineering"]="As an engineer, you can make a gyrochronatom yourself."},kw={"badlands","contraption","coolant heads prevail","gyrochronatom","kharanos","lotwil veriatus"},rel={"npc:lotwil-veriatus","quest:713","zone:badlands","subzone:kharanos"},m={start="Lotwil Veriatus",["end"]="Lotwil Veriatus",level="37",id=714},src={"Gyro... What?"}}
E["quest:716"] = {t="quest",n="Stone Is Better than Cloth",z="badlands",s="In the Badlands, Lucien Tosselwrench has a gift for you, though his work is not finished. The extra stones you gathered are ready, but he still needs patterned bronze bracers.",h="In the Badlands, Lucien Tosselwrench has a gift for you, though his work is not finished.",sec={{t="A Thank-You for Your Trouble",b="After your work for Lotwil on his third Study of the Elements: Rock request, Lucien Tosselwrench admits Lotwil can be cheap. He means to make it up to you with fine enchanted bracers fashioned from the extra stones you gathered. They may help guard you against the coming atrocity of Lotwil's newest invention.",sp=0},{t="What Lucien Needs",b="To finish the bracers, Lucien needs patterned bronze bracers of the kind a blacksmith makes. He warns you not to wait long. No one knows what happens next.",sp=0}},faq={{q="Who offers to craft the bracers?",a="Lucien Tosselwrench offers to make enchanted bracers from your extra stones in the Badlands.",al={"who gives stone is better than cloth","quest giver","lucien tosselwrench"}},{q="Why is Lucien making this armor for you?",a="Lucien knows Lotwil can be cheap and wants to repay you for your trouble. He says the bracers may also guard you against Lotwil's newest invention.",al={"why make bracers","lucien motive","lotwil cheap"}},{q="What does Lucien need to finish crafting the bracers?",a="Lucien needs patterned bronze bracers, the kind a blacksmith makes, to finish the enchanted bracers.",al={"what item is needed","required items","patterned bronze bracers needed"}},{q="What comes before this quest?",a="It follows your work on Lotwil's third Study of the Elements: Rock request.",al={"previous quest","prerequisite for stone is better than cloth"}}},ang={["profession:Blacksmithing"]="As a blacksmith, you can make the bronze bracers Lucien needs."},kw={"badlands","elemental rock","enchanted bracers","lotwil veriatus","lucien tosselwrench","patterned bronze bracers"},rel={"quest:712","zone:badlands"},m={start="Lucien Tosselwrench",["end"]="Lucien Tosselwrench",level="42",faction="Neutral",id=716},src={"Stone Is Better than Cloth"}}
E["quest:717"] = {t="quest",n="Tremors of the Earth",z="badlands",s="At Lethlor, Garek fears the drakes may break free. Black dragons now dwell there, and ogres have taken the Sign of the Earth. So he sends you to free the drakes and kill them.",h="At Lethlor, Garek fears the drakes may break free.",sec={{t="A Prison Failing",b="At Lethlor, Garek fears Blacklash and Hematus may escape their prison. Black dragons now dwell there, and ogres have taken the Sign of the Earth. Garek sees no safer course. The drakes must die.",sp=0},{t="Breaking the Seal",b="Three runestones hold the drakes, and the Sign of the Earth is needed to release them. You use the Sign at the Pillars of Amethyst, Opal and Diamond, then place the runestones in the Seal of the Earth. Blacklash and Hematus are freed, and you slay them. Garek asks you to bring back Blacklash's Bindings, the Chains of Hematus and the Sign of the Earth.",sp=0},{t="After the Deed",b="After the drakes die, Garek says the Kirin Tor need not fret over Lethlor's prisoners anymore. He plans to report his success to his master, Krasus. Krasus will surely be pleased.",sp=1}},faq={{q="Who are Blacklash and Hematus?",a="Blacklash and Hematus are drakes held behind a seal at Lethlor.",al={"blacklash and hematus","who are the drakes","what is imprisoned in lethlor"}},{q="Why must the drakes be killed instead of kept locked away?",a="Garek can no longer be sure the drakes will stay imprisoned. Black dragons now dwell at Lethlor, and ogres have taken the Sign of the Earth.",al={"why kill blacklash","why break the prison","why slay hematus"}},{q="How is the prison unsealed?",a="Use the Sign of the Earth at the Pillars of Amethyst, Opal and Diamond. Then place the three runestones in the Seal of the Earth.",al={"how to open seal of the earth","how to summon blacklash","how to break the drakes out"}},{q="What must be brought back to Garek?",a="Bring Garek Blacklash's Bindings, the Chains of Hematus and the Sign of the Earth.",al={"what to return to garek","blacklash's bindings","chains of hematus"}},{q="What comes before this quest?",a="It follows an earlier Tremors of the Earth.",al={"previous quest","prerequisite for tremors of the earth"}}},ang={["faction:Alliance"]="As an Alliance member, Garek's request is meant for you."},kw={"blacklash","garek","hematus","kirin tor","krasus","lethlor ravine","runestones","seal of the earth","sign of the earth","tremors of the earth"},rel={"zone:badlands","subzone:lethlor-ravine"},m={start="Garek",["end"]="Garek",level="50",faction="Alliance",id=717,ri={"Blacklash's Bindings","Chains of Hematus"}},src={"Tremors of the Earth (2)"}}
E["quest:718"] = {t="quest",n="Mirages",z="badlands",s="In the Badlands, Sigrun Ironhew's party has fled the Uldaman excavation and gone hungry.",h="In the Badlands, Sigrun Ironhew's party has fled the Uldaman excavation and gone hungry.",sec={{t="Hungry in the Badlands",b="Sigrun's party fled the Uldaman dig in such haste that they took little with them. They left wagons and supply crates behind, and ogres from Camp Kosh have been picking through them. The ogres took the cart with all the party's weapons. Since then, the party has had no food. Sigrun admits the trouble is embarrassing and asks you to retrieve the supply crate.",sp=0},{t="On Your Return",b="When you return, Sigrun admits to swallowing a mouthful of sand while you were away. The evening brings a better prospect. Tonight, the party will go out to find food and eat like kings.",sp=1}},faq={{q="Who is Sigrun Ironhew?",a="Sigrun Ironhew is with a party that fled the Uldaman excavation site in a hurry and now has no food in the Badlands.",al={"sigrun ironhew","who gives mirages","who is sigrun"}},{q="Why is Sigrun's party starving?",a="Ogres took the cart carrying all the party's weapons. Since then, Sigrun's party has had no food.",al={"why are they hungry","why no food","sigrun food problem"}},{q="Who took the abandoned supplies?",a="Ogres from Camp Kosh have been picking through the equipment left behind.",al={"who stole the crate","camp kosh ogres","who took weapons"}},{q="What is Sigrun hoping to get back?",a="Sigrun hopes to get back the supply crate left behind when the party fled the excavation site.",al={"supply crate","what to retrieve for sigrun"}}},ang={["faction:Alliance"]="As an Alliance member, you can help Sigrun Ironhew."},kw={"badlands","camp kosh","excavation","mirages","ogres","sigrun ironhew","supply crate","uldaman"},rel={"zone:badlands","subzone:camp-kosh","subzone:uldaman"},m={start="Sigrun Ironhew",["end"]="Sigrun Ironhew",level="38",faction="Alliance",id=718,ri={"Supply Crate (Blasted Lands)"}},src={"Mirages"}}
E["quest:719"] = {t="quest",n="A Dwarf and His Tools",z="badlands",s="Prospector Ryedol escaped an attack on his dig site and now seeks his lucky pick. Dark Iron dwarves resembling the Shadowforge clan are all around.",h="Prospector Ryedol escaped an attack on his dig site and now seeks his lucky pick.",sec={{t="Raiders at the Dig",b="Dark Iron dwarves resembling the Shadowforge clan attacked the excavation site where Ryedol worked. Nearly everyone died, including his boss, Hammertoe. Ryedol barely escaped with his life. The site lies north of where he waits.",sp=0},{t="A Lucky Pick",b="Prospector Ryedol is trying to recover supplies lost in the attack, especially his lucky pick. One of the Dark Iron dwarves has it, though Ryedol does not know which one. He hopes you will help and waits south of Hammertoe's Dig Site.",sp=0}},faq={{q="Who is Prospector Ryedol?",a="Prospector Ryedol worked at an excavation site attacked by Dark Iron dwarves. He barely escaped and now waits south of Hammertoe's Dig Site.",al={"who is ryedol","prospector ryedol","who gives a dwarf and his tools"}},{q="Who attacked the excavation camp?",a="Dark Iron dwarves resembling the Shadowforge clan attacked the excavation site.",al={"who attacked the dig","who attacked hammertoe","what attacked the camp"}},{q="What happened to Hammertoe?",a="Hammertoe was Ryedol's boss and was among those killed in the attack.",al={"who is hammertoe","is hammertoe alive","what happened to boss hammertoe"}},{q="Where is the lucky pick located?",a="Ryedol believes one of the Dark Iron dwarves has the lucky pick, though he does not know which one.",al={"where is ryedols lucky pick","how to find the pick","who has ryedols pick"}}},kw={"badlands","dark iron","excavation","hammertoe","lucky pick","ryedol","shadowforge"},rel={"npc:prospector-ryedol","zone:badlands"},m={start="Prospector Ryedol",["end"]="Prospector Ryedol",level="35",faction="Alliance",id=719,ri={"Ryedol's Lucky Pick"}},src={"A Dwarf and His Tools"}}
E["quest:720"] = {t="quest",n="A Sign of Hope",z="badlands",s="Hammertoe Grez lives, and a chalk plea on a crumpled map calls Prospector Ryedol to help. The note says they are taking Hammertoe to Uldaman.",h="Hammertoe Grez lives, and a chalk plea on a crumpled map calls Prospector Ryedol to help.",sec={{t="Words in Chalk",b="Hammertoe leaves a brief plea for Ryedol in chalk on a crumpled map. The note says they are taking Hammertoe to Uldaman and asks for help. Tell Prospector Ryedol that Hammertoe Grez lives.",sp=0}},faq={{q="What is written on the crumpled map?",a="Hammertoe's chalk note is addressed to Ryedol. It says they are taking Hammertoe to Uldaman and asks for help.",al={"what does the note say","chalk message on map","crumpled map text"}},{q="Who is Prospector Ryedol?",a="Prospector Ryedol is the one the note addresses. Find him and tell him that Hammertoe Grez lives.",al={"who is ryedol","where to bring crumpled map"}},{q="Where does the message say Hammertoe Grez is being taken?",a="The message says Hammertoe Grez is being taken to Uldaman.",al={"where is hammertoe taken","where is grez taken"}}},kw={"a sign of hope","badlands","chalk note","crumpled map","hammertoe grez","prospector ryedol","uldaman"},rel={"npc:prospector-ryedol","subzone:uldaman","zone:badlands"},m={start="Crumpled Map",["end"]="Prospector Ryedol",level="35",faction="Alliance",id=720},src={"A Sign of Hope"}}
E["quest:724"] = {t="quest",n="Prospect of Faith",z="badlands",s="In the Badlands, Prospector Ryedol sends you to Ironforge with Hammertoe's Amulet. Historian Karnik and Hammertoe sought Uldaman's lost artifacts together. Ryedol suspects the Shadowforge learned they knew more than they let on.",h="In the Badlands, Prospector Ryedol sends you to Ironforge with Hammertoe's Amulet.",sec={{t="A Message for Ironforge",b="Prospector Ryedol sends you to Historian Karnik in Ironforge. Tell Karnik what happened to Hammertoe and place the amulet in his hands. Karnik will decide what to do next.",sp=0},{t="Karnik's Welcome",b="Historian Karnik will not hear another traveler's tale until he sees the amulet. Then he sets his mourning for Hammertoe aside and calls up Hammertoe's spirit to show you the amulet's worth.",sp=1}},faq={{q="Who starts this quest?",a="Prospector Ryedol in the Badlands sends you to Ironforge with Hammertoe's Amulet.",al={"who gives prospect of faith","prospect of faith questgiver","where to start prospect of faith"}},{q="Where is Historian Karnik located?",a="Historian Karnik is in Ironforge.",al={"where is karnik","historian karnik location","karnik ironforge"}},{q="Why was Historian Karnik chosen?",a="Karnik and Hammertoe sought Uldaman's lost artifacts together, so Ryedol trusts Karnik to know what to do next.",al={"why send the amulet to karnik","karnik connection"}},{q="What comes after this quest?",a="Karnik's story continues with Passing Word of a Threat.",al={"next quest after prospect of faith","what follows prospect of faith"}}},kw={"badlands","hammertoe","hammertoes amulet","historian karnik","ironforge","prospect of faith","prospector ryedol","shadowforge","uldaman"},rel={"npc:prospector-ryedol","zone:ironforge","quest:725","quest:723","quest:720","subzone:uldaman","zone:badlands"},m={start="Prospector Ryedol",["end"]="Historian Karnik",level="40",faction="Alliance",id=724},src={"Prospect of Faith (2)"}}
E["quest:727"] = {t="quest",n="To Ironforge for Yagyin's Digest",z="badlands",s="Theldurin the Lost sends you to Ironforge with a sigil. In a shop in the Forlorn Cavern, Gerrig Bonegrip is meant to take you for one of the people Theldurin fled, so you can ask him for Yagyin's Digest.",h="Theldurin the Lost sends you to Ironforge with a sigil.",sec={{t="A Book Written Long Ago",b="The Tablet has taught Theldurin much, yet questions remain. Yagyin wrote a digest ages ago, and the people Theldurin fled keep copies in many places. Their most learned study it. Theldurin believes its vast knowledge can offer protection, so he wants you to bring it back.",sp=0},{t="The Shop in the Forlorn Cavern",b="Gerrig Bonegrip keeps a shop in Ironforge's Forlorn Cavern. Theldurin gives you the Sigil of the Hammer to show Gerrig. Then Gerrig should take you for one of the people Theldurin fled. Ask him for Yagyin's Digest.",sp=0},{t="Gerrig's Greeting",b="Gerrig Bonegrip warns you to watch what you touch in the shop. Knowledge can be deadly. When you show the sigil, Gerrig greets you as brother or sister and praises the dwellers beneath.",sp=1}},faq={{q="Why does Theldurin want Yagyin's Digest?",a="The Tablet tells Theldurin much, yet leaves questions unanswered. Yagyin's digest, written ages ago, holds vast knowledge that can offer protection. Theldurin wants you to bring it back.",al={"why need yagyins digest","what is yagyins digest","yagyin digest purpose"}},{q="Where is Gerrig Bonegrip?",a="In Ironforge's Forlorn Cavern, where he keeps a shop.",al={"where is gerrig bonegrip","gerrig bonegrip location","who is gerrig"}},{q="What is the Sigil of the Hammer used for?",a="Theldurin gives you the Sigil of the Hammer to show Gerrig Bonegrip. He wants Gerrig to take you for one of the people Theldurin fled.",al={"what does the sigil do","sigil of the hammer use","why use the sigil"}},{q="Where does this fit in the chain?",a="It follows Solution to Doom with Theldurin the Lost. The chain continues with the next step.",al={"what comes before to ironforge for yagyins digest","chain order yagyin"}}},kw={"badlands","forlorn cavern","gerrig bonegrip","ironforge","sigil of the hammer","theldurin the lost","yagyin's digest"},rel={"npc:theldurin-the-lost","npc:gerrig-bonegrip","subzone:forlorn-cavern","zone:ironforge","zone:badlands"},m={start="Theldurin the Lost",["end"]="Gerrig Bonegrip",level="40",faction="Alliance",id=727},src={"To Ironforge for Yagyin's Digest"}}
E["quest:728"] = {t="quest",n="To the Undercity for Yagyin's Digest",z="badlands",s="Theldurin the Lost sends you to the Undercity of Lordaeron with a sigil for Keeper Bel'dugur. He wants the keeper to mistake you for one of the people he fled, and asks you to find Yagyin's Digest.",h="Theldurin the Lost sends you to the Undercity of Lordaeron with a sigil for Keeper Bel'dugur.",sec={{t="A Book Written Long Ago",b="The tablet has answered much for Theldurin, yet questions remain. Yagyin wrote a digest ages ago, and the people Theldurin fled keep copies in many places. Their most learned study its pages. Theldurin believes its vast knowledge can protect them, so he wants you to bring it back.",sp=0},{t="The Keeper in the Undercity",b="Keeper Bel'dugur waits in the Undercity of Lordaeron. Theldurin gives you the Sigil of the Hammer to show the keeper, who is to take you for one of the people he fled. Ask Bel'dugur for the digest.",sp=0},{t="A Word of Caution",b="Keeper Bel'dugur welcomes you as an eager seeker of the collection. Knowledge, the keeper warns, gives power to the strong but drives the weak mad. After you show the sigil, Bel'dugur urges discretion with such signs. Some doubt their pledge is righteous, while others would see them fail if they knew of it. Those who share the pledge must be careful, watchful, and patient.",sp=1}},faq={{q="Who sends you to the Undercity?",a="Theldurin the Lost sends you to find Keeper Bel'dugur and gives you the Sigil of the Hammer to carry.",al={"who starts this quest","who gives to the undercity for yagyin's digest","quest giver"}},{q="What is the Sigil of the Hammer for?",a="Theldurin gives you the Sigil of the Hammer to show Keeper Bel'dugur, so the keeper will take you for one of the people Theldurin fled.",al={"sigil of the hammer use","why do i need the sigil","what does the sigil do"}},{q="What is Yagyin's Digest?",a="Yagyin's Digest is a book Yagyin wrote ages ago. Theldurin says it holds vast knowledge, studied by the most learned among the people he fled.",al={"what is yagyins digest","who is yagyin","yagyin book"}},{q="Where is Keeper Bel'dugur?",a="Keeper Bel'dugur is in the Undercity of Lordaeron.",al={"keeper bel'dugur location","where to find keeper beldugur","beldugur undercity"}},{q="What came before this?",a="Solution to Doom came before this.",al={"previous quest","what comes before this","solution to doom connection"}}},kw={"badlands","bel'dugur","digest","hammer","sigil","theldurin","undercity","yagyin"},rel={"npc:theldurin-the-lost","npc:keeper-bel-dugur","zone:undercity","quest:736","zone:badlands","topic:lordaeron"},m={start="Theldurin the Lost",["end"]="Keeper Bel'dugur",level="40",faction="Horde",id=728},src={"To the Undercity for Yagyin's Digest"}}
E["quest:732"] = {t="quest",n="Tremors of the Earth",z="badlands",s="Garek asks for your help after hearing all you have done for Sigrun. His master, Krasus of the Kirin Tor, sent him to the Badlands to stop trouble brewing in Lethlor Ravine. First, he needs the stolen Sign of the Earth.",h="Garek asks for your help after hearing all you have done for Sigrun.",sec={{t="A Matter Kept Close",b="Krasus of the Kirin Tor sent Garek to the Badlands to stop trouble brewing in Lethlor Ravine. He cannot tell you the exact assignment, only that it matters greatly. Roving ogres took the Sign of the Earth, and Garek needs it back before he can tell you more. They are sometimes seen around Camp Boff.",sp=0},{t="The Wandering Ogres",b="Ogres wander from camp to camp across the Badlands. Rising heat and swirling winds make their trail hard to follow. Garek has heard they sometimes pass through Camp Boff, so look there if you lose track of them.",sp=0},{t="Garek Explains",b="When you return with the Sign, Garek tells you the Dark Iron dwarves of Angor Fortress made it to bind Deathwing's twin lieutenants, the ruthless Blacklash and Hematus.",sp=1}},faq={{q="Who is Garek working for?",a="Krasus of the Kirin Tor is Garek's master. He sent Garek to the Badlands to stop trouble brewing in Lethlor Ravine.",al={"who sent garek","garek master","krasus badlands"}},{q="What is the Sign of the Earth?",a="Wandering ogres stole the Sign of the Earth, and Garek needs it back before he will tell you more.",al={"sign of the earth","what is the sign of the earth","sign of earth lore"}},{q="Where can the wandering ogres be found?",a="The ogres roam between camps across the Badlands. Garek has heard they sometimes pass through Camp Boff.",al={"where are the ogres","ogre camp boff","where is sign of the earth"}},{q="Why does Garek keep the assignment secret?",a="Garek will not share the assignment or what work it calls for. He says only that it matters greatly.",al={"why secret","garek secret assignment"}}},kw={"angor fortress","camp boff","dark iron","deathwing","garek","kirin tor","krasus","lethlor ravine","sign of the earth"},rel={"zone:badlands","subzone:lethlor-ravine","quest:718","npc:deathwing"},m={start="Garek",["end"]="Garek",level="43",faction="Alliance",id=732,ri={"Sign of the Earth"}},src={"Tremors of the Earth"}}
E["quest:733"] = {t="quest",n="Scrounging",z="badlands",s="At Sigrun Ironhew's camp, defenses and supplies wait on scrap metal. She needs seven pieces, and nearby ogres carry plenty.",h="At Sigrun Ironhew's camp, defenses and supplies wait on scrap metal.",sec={{t="A Camp Short of Materials",b="Sigrun Ironhew needs materials for the camp's defenses and other needs. The Prospector worries about the camp's condition, so Sigrun wants to begin work soon. Scrap metal is what she lacks.",sp=0},{t="The Ogres' Scrap",b="Nearby ogres carry scrap metal, adding weight to talk of siege engines in the Badlands. Their main camp, Dustbelch Grotto, lies a long trek west of Sigrun's camp.",sp=0}},faq={{q="Who is asking for the scrap metal?",a="Sigrun Ironhew needs scrap metal to build defenses and supply the camp.",al={"quest giver","who gives scrounging","sigrun"}},{q="Why does the camp need scrap metal?",a="The camp lacks materials for defenses and other needs. The Prospector worries about its condition.",al={"why need scrap metal","purpose of scrap metal","defenses"}},{q="Where can the scrap metal be found?",a="Nearby ogres carry scrap metal. Their main camp, Dustbelch Grotto, lies a long trek west of Sigrun's camp.",al={"scrap metal location","where to get scrap metal","ogre camp"}},{q="What comes before this?",a="It follows Mirages.",al={"previous quest","scrounging prerequisite"}}},kw={"badlands","dustbelch grotto","explorers' league","ironforge","ogres","scrap metal","scrounging","sigrun ironhew"},rel={"quest:718","zone:badlands"},m={start="Sigrun Ironhew",["end"]="Sigrun Ironhew",level="40",faction="Alliance",id=733,ri={"Scrap Metal (Scrounging)"}},src={"Scrounging"}}
E["quest:734"] = {t="quest",n="This Is Going to Be Hard",z="badlands",s="In the Badlands, Lotwil Veriatus sends you to Lucien Tosselwrench for a needed cog #5. Bring it back to Lotwil.",h="In the Badlands, Lotwil Veriatus sends you to Lucien Tosselwrench for a needed cog #5.",sec={{t="Cog Number Five",b="Lotwil Veriatus turns his attention to the shackles, then sends you to Lucien Tosselwrench. He needs a cog #5 and asks you to bring it back to him.",sp=0},{t="Lucien's Verdict",b="When you mention cog #5, Lucien Tosselwrench sounds doubtful about how things will go.",sp=1}},faq={{q="Who gives this quest?",a="Lotwil Veriatus asks you while working on a set of shackles in the Badlands.",al={"who starts this quest","lotwil veriatus quest","quest giver"}},{q="What does Lotwil need?",a="Lotwil needs a cog #5. He asks you to bring it back after speaking with Lucien Tosselwrench.",al={"what does lotwil want","which cog","cog 5"}},{q="Who do I speak to about the cog?",a="Lotwil sends you to Lucien Tosselwrench in the Badlands.",al={"where to find cog 5","who is lucien","lucien tosselwrench"}}},kw={"badlands","cog #5","lotwil veriatus","lucien tosselwrench","shackles"},rel={"npc:lotwil-veriatus","zone:badlands"},m={start="Lotwil Veriatus",["end"]="Lucien Tosselwrench",level="42",faction="Neutral",id=734},src={"This Is Going to Be Hard"}}
E["quest:737"] = {t="quest",n="Forbidden Knowledge",z="badlands",s="Yagyin's Digest is in your care, bound for Theldurin the Lost and kept from unfriendly hands.",h="Yagyin's Digest is in your care, bound for Theldurin the Lost and kept from unfriendly hands.",sec={{t="A Book That Burns",b="Gerrig Bonegrip in Ironforge or Keeper Bel'dugur in the Undercity gives you Yagyin's Digest. Keep it from unfriendly hands as you carry it to Theldurin the Lost. It holds many truths, and truth has a way of burning.",sp=0},{t="Theldurin's Hope",b="Theldurin cries out that hope still glimmers. Your efforts may yet save them all, he says, and bring a monument and shrine with your name praised for generations.\n\nThat hope holds only while THEY remain below the surface. If THEY rise free, everyone becomes worm food.",sp=1}},faq={{q="What item needs to be delivered?",a="Yagyin's Digest needs to be delivered. It holds many truths and must be kept from unfriendly hands.",al={"what book is this","what is yagyin's digest","what do i bring"}},{q="Who receives the digest?",a="Theldurin the Lost is to receive Yagyin's Digest.",al={"who gets the book","who do i turn this into","where does the digest go"}},{q="What came before this?",a="It follows the step where you fetched three items in exchange for Yagyin's Digest.",al={"previous quest","what leads to this","what quest comes before forbidden knowledge"}}},kw={"badlands","forbidden knowledge","the star the hand and the heart","theldurin the lost","yagyin's digest"},rel={"npc:theldurin-the-lost","zone:badlands"},m={["end"]="Theldurin the Lost",level="40",faction="Both",id=737},src={"Forbidden Knowledge (Classic)"}}
E["quest:739"] = {t="quest",n="Murdaloc",z="badlands",s="Agmond lies dead in the Badlands, with Murdaloc scratched into the sandstone beside his hand. Slay his killer and carry word to Prospector Ironband in Loch Modan.",h="Agmond lies dead in the Badlands, with Murdaloc scratched into the sandstone beside his hand.",sec={{t="A Name in the Sandstone",b="Blood marks Agmond's trail from the west, crossing stone and sand. It shows how far the dwarf crawled before he died. Beside his still hand, one word is scratched into the Badlands sandstone: Murdaloc. Slay Agmond's killer and a number of Stonevault Bonesnappers, then carry the news to Prospector Ironband in Loch Modan.",sp=0},{t="Ironband's Reply",b="Prospector Ironband receives the news with a sober face. He remembers Agmond as strong of arm, fierce with a hammer, and thick of skull. Ironband says cursed troggs killed Agmond. He believes Agmond took a good number of them down along the way.",sp=1}},faq={{q="Who was Agmond?",a="Agmond was a dwarf who oversaw the excavation sites in the Badlands for Prospector Ironband. Your search for him ended at a skeleton.",al={"who is agmond","agmond lore"}},{q="Who is Murdaloc?",a="Murdaloc is the name scratched into the sandstone beside Agmond's dead hand. Slay Agmond's killer, Murdaloc.",al={"what is murdaloc","murdaloc lore"}},{q="Where does the report need to go?",a="Carry the report to Prospector Ironband in Loch Modan.",al={"who do i tell about murdaloc","where is ironband"}}},kw={"agmond","badlands","loch modan","murdaloc","prospector ironband","stonevault bonesnapper","trogg"},rel={"quest:738","npc:prospector-ironband","zone:badlands","zone:lochmodan","topic:trogg","topic:dwarf"},m={start="Battered Dwarven Skeleton",["end"]="Prospector Ironband",level="42",faction="Alliance",id=739},src={"Murdaloc (quest)"}}
E["quest:777"] = {t="quest",n="This Is Going to Be Hard",z="badlands",s="Behind cover, Lucien Tosselwrench waits while you carry cog #5 to Lotwil Veriatus.",h="Behind cover, Lucien Tosselwrench waits while you carry cog #5 to Lotwil Veriatus.",sec={{t="Behind Cover",b="Lucien Tosselwrench gives you the cog for Lotwil Veriatus. Then he waits behind cover and welcomes you to join him. Lotwil is still bent over the shackles when you arrive. Without looking up, he holds out his hand and waggles his fingers for the cog.",sp=0},{t="Making History",b="Lotwil takes the cog and calls it perfect. He tells you to stand back as he prepares to make more history. Then he carries on working feverishly.",sp=1}},faq={{q="Who hands over the cog for Lotwil?",a="Lucien Tosselwrench gives you cog #5 to carry to Lotwil Veriatus.",al={"who gives the cog","where do i get cog 5","lucien cog"}},{q="Where does Lucien go?",a="Lucien heads behind cover and welcomes you to join him.",al={"why is lucien hiding","lucien cover"}},{q="What is Lotwil doing when you bring the cog?",a="Lotwil is working on a set of shackles. Without looking up, he holds out his hand and waggles his fingers impatiently for the cog.",al={"what is lotwil doing","lotwil shackles","lotwil progress"}}},kw={"badlands","cog 5","lotwil veriatus","lucien tosselwrench","shackles","this is going to be hard"},rel={"quest:734","npc:lotwil-veriatus","zone:badlands"},m={start="Lucien Tosselwrench",["end"]="Lotwil Veriatus",level="42",faction="Neutral",id=777},src={"This Is Going to Be Hard (2)"}}
E["quest:778"] = {t="quest",n="This Is Going to Be Hard",z="badlands",s="In the Badlands, Lotwil Veriatus is ready to summon a powerful elemental.",h="In the Badlands, Lotwil Veriatus is ready to summon a powerful elemental.",sec={{t="A Groundbreaking Day",b="Lotwil calls out that the shackles are finished. The time has come. He asks Lucien and Servo to witness the summoning with you. Alchemy, engineering and the arcane come together in the shackles, and Lotwil expects a powerful elemental to answer on this groundbreaking day.",sp=0},{t="After the Summoning",b="The summoning ends differently than Lotwil expected. After you defeat the Fam'retor Guardian, Lotwil asks you to bring back the Shackles of Elemental Binding. He cannot say what went wrong. Still, he is glad the magics were ready to send the creature back to its own plane.",sp=1}},faq={{q="Who is Lotwil Veriatus?",a="Lotwil Veriatus made the Shackles of Elemental Binding by joining alchemy, engineering and the arcane. Lucien and Servo are with him in the Badlands.",al={"who is lotwil","lotwil veriatus"}},{q="What are the Shackles of Elemental Binding?",a="The Shackles of Elemental Binding combine alchemy, engineering and the arcane. Lotwil has just finished them for the powerful elemental he means to summon.",al={"what are the shackles","shackles of elemental binding"}},{q="Who does Lotwil call to bear witness?",a="Lotwil calls on Lucien and Servo to witness the summoning with you.",al={"who is lucien","who is servo"}},{q="What comes before this step?",a="Before this, you brought cog #5 to Lotwil.",al={"previous quest","what led to this"}}},kw={"badlands","elemental","fam'retor guardian","lotwil veriatus","lucien","servo","shackles of elemental binding"},rel={"npc:lotwil-veriatus","zone:badlands"},m={start="Lotwil Veriatus",["end"]="Lotwil Veriatus",level="45",id=778,ri={"Lotwil's Shackles of Elemental Binding"}},src={"This Is Going to Be Hard (3)"}}
E["quest:782"] = {t="quest",n="Broken Alliances",z="badlands",s="Gorn sends you from Kargath to reclaim what the ogres took. He seeks to restore the Horde’s honor after its alliance with Deathwing. Boss Tho’grun, hired to find the Sign of the Earth, betrayed the Horde and kept it.",h="Gorn sends you from Kargath to reclaim what the ogres took.",sec={{t="A Hired Band Turns",b="During the Second War, the Horde fought beside Deathwing. His lieutenants Blacklash and Hematus were later imprisoned far to the east in Lethlor Ravine. Gorn believes these old, depraved allies must be silenced to restore the Horde’s honor.\n\nThe Horde needed the Sign of the Earth to open the drakes’ prison, so it hired ogre mercenaries led by Boss Tho’grun to find the sign. Tho’grun turned against the Horde, overwhelmed its forces and kept it.",sp=0},{t="Camp Boff",b="Gorn sends you southeast of Kargath to Camp Boff. Kill Tho’grun and bring back the Sign of the Earth. Gorn will be glad to see Tho’grun dead. The ogres no longer belong to the Horde.",sp=0},{t="What the Sign Opens",b="Gorn expects the ogres to fall into disarray after Tho’grun’s death. That will be a small victory, and may lead to a larger one.\n\nWith the Sign of the Earth in Horde hands, the black drakes’ prison in Lethlor can be opened. They will be freed from endless imprisonment, only to meet their doom.",sp=1}},faq={{q="Who is Gorn?",a="Gorn is a Horde figure in Kargath who sends you after the Sign of the Earth. He wants to restore the Horde’s honor by silencing its depraved allies of old.",al={"who gives broken alliances","gorn kargath","gorn lore"}},{q="Why does Gorn want Boss Tho'grun dead?",a="The Horde hired Boss Tho’grun and his ogre mercenaries to obtain the Sign of the Earth. Tho’grun betrayed them, overwhelmed them and kept the sign.",al={"why kill thogrun","thogrun betrayal","boss thogrun lore"}},{q="Where is Camp Boff?",a="Camp Boff lies southeast of Kargath.",al={"camp boff location","where is thogrun","find boss thogrun"}},{q="What is the Sign of the Earth?",a="The Sign of the Earth is a key needed to open the drakes’ prison in Lethlor Ravine.",al={"sign of the earth","what does sign of the earth do"}},{q="Which dragons are imprisoned in Lethlor Ravine?",a="Blacklash and Hematus are two of Deathwing’s lieutenants. They were imprisoned in Lethlor Ravine after the Horde fought beside Deathwing during the Second War.",al={"who is in lethlor ravine","blacklash and hematus","deathwing lieutenants"}}},kw={"badlands","blacklash","camp boff","deathwing","gorn","hematus","kargath","lethlor ravine","sign of the earth","tho'grun"},rel={"subzone:kargath","subzone:lethlor-ravine","npc:deathwing","topic:second-war","topic:horde","zone:badlands"},m={start="Gorn",["end"]="Gorn",level="43",faction="Horde",id=782,ri={"Sign of the Earth"}},src={"Broken Alliances (1)"}}
E["quest:793"] = {t="quest",n="Broken Alliances",z="badlands",s="Gorn sends you east into Lethlor Ravine to free two black drakes bound by the Seal of the Earth. This follows the first Broken Alliances.",h="Gorn sends you east into Lethlor Ravine to free two black drakes bound by the Seal of the Earth.",sec={{t="Three Runestones",b="Three runestones keep the Seal of the Earth closed, one in each of Lethlor Ravine’s Diamond, Opal and Amethyst pillars. Gorn gives you the Sign of the Earth, which draws the stones out and opens the seal.\n\nCountless drakes live in the ravine, and Blacklash and Hematus are formidable foes. Gorn wants both dead, with their bindings brought back to him.",sp=0},{t="What Gorn Makes of It",b="Gorn says the black dragonflight remains allied with the renegade Blackrock orcs. He believes dragons and orcs alike must be reined in or cast out. With Blacklash and Hematus dead, the Horde can look west toward Blackrock Spire.",sp=1}},faq={{q="Who gives this quest?",a="Gorn sends you into Lethlor Ravine, as the next step after the first Broken Alliances.",al={"broken alliances quest giver","gorn location","who gives broken alliances"}},{q="Where is Lethlor Ravine located?",a="Lethlor Ravine lies at the far eastern end of the Badlands, where countless drakes make their home.",al={"lethlor ravine location","how to get to lethlor ravine","where is lethlor ravine"}},{q="How do you free Blacklash and Hematus?",a="Use the Sign of the Earth to draw a runestone from each of the three pillars. Set the stones into the Seal of the Earth to free both drakes.",al={"how to summon blacklash","seal of the earth","pillars of diamond opal amethyst"}},{q="What must be brought back to Gorn?",a="Once both drakes are dead, bring Gorn the bindings of Blacklash, the chains of Hematus and the Sign of the Earth.",al={"broken alliances turn in items","what does gorn want back","bindings of blacklash"}}},kw={"black dragonflight","blacklash","blackrock orcs","gorn","hematus","lethlor ravine","seal of the earth","sign of the earth"},rel={"quest:782","subzone:lethlor-ravine","topic:black-dragonflight","zone:badlands"},m={start="Gorn",["end"]="Gorn",level="50",faction="Horde",id=793,ri={"Blacklash's Bindings","Chains of Hematus"}},src={"Broken Alliances (2)"}}
E["subzone:agmond-s-end"] = {t="subzone",n="Agmond's End",z="badlands",s="Stonevault troggs overrun Agmond's End, the ruined dwarven dig in the southern Badlands. Prospector Agmond led the search until the creatures killed him and his miners.",h="Stonevault troggs overrun Agmond's End, the ruined dwarven dig in the southern Badlands.",sec={{t="A Gruesome Excavation",b="Dwarven prospectors came to Agmond's End in search of ancient relics and the earth's buried history. Then troggs surged from nearby crevices and overwhelmed the miners. Agmond fell in the attack, and the site took his name. Stonevault troggs now infest the ruined dig, among shattered crates and abandoned tools.",sp=0},{t="A Lonely Neighbor",b="Near the ruined excavation, Theldurin the Lost lives at a solitary camp. The dwarf's sanity has long since frayed. Yet he remains one of the few souls willing to brave the southern desert near the doomed site.",sp=0}},faq={{q="Who was Agmond?",a="Agmond was a dwarven prospector who led an excavation in the southern Badlands. Troggs emerged from underground and killed him and his expedition.",al={"who is agmond","agmond lore"}},{q="What creatures inhabit Agmond's End?",a="Hostile Stonevault troggs overrun the ruined dig. They killed the dwarven miners and claimed the camp and surrounding crags.",al={"mobs at agmonds end","who lives here"}},{q="Who lives near Agmond's End?",a="Theldurin the Lost is a hermit dwarf who keeps a camp near Agmond's End in the southern hills. He watches the barren landscape.",al={"npc nearby","theldurin location"}},{q="Why were dwarves digging here in the first place?",a="Dwarven prospectors searched the Badlands for titan artifacts, ancient ruins, and rich mineral seams. Many underestimated the savage creatures lurking underground.",al={"why dwarven dig","purpose of excavation"}}},ang={["race:Dwarf"]="As a dwarf, you can see the danger in digging into ancient earthen ground without enough martial support."},kw={"agmond","agmond's end","badlands","dig site","prospector","theldurin the lost","trogg"},rel={"zone:badlands","npc:theldurin-the-lost","topic:trogg"},src={"Agmond's End"}}
E["subzone:camp-kosh"] = {t="subzone",n="Camp Kosh",z="badlands",s="At Camp Kosh, Dustbelcher ogres prey on caravans crossing the northern Badlands. They scavenge abandoned gear from roads leading toward Kargath and the Searing Gorge.",h="At Camp Kosh, Dustbelcher ogres prey on caravans crossing the northern Badlands.",sec={{t="A Den of Scavengers",b="In the northern Badlands, Dustbelcher ogres make their northernmost camp at Camp Kosh. Their tribe also holds nearby camps called Boff, Cagg, and Wurg. From these camps, they strike vulnerable supply lines bound for Kargath or traveling west into the Searing Gorge. When dwarven prospectors led by Sigrun Ironhew fled the excavation at Uldaman, the ogres raided their abandoned wagons. They carried food rations and weapons back into Camp Kosh.",sp=0}},faq={{q="Who lives in Camp Kosh?",a="Dustbelcher ogres live in Camp Kosh, one of several small camps their tribe holds across the Badlands.",al={"camp kosh mobs","who is at camp kosh","ogres camp kosh"}},{q="Why is Camp Kosh located here?",a="From Camp Kosh in the northern Badlands, Dustbelcher ogres can ambush supply caravans and unwary travelers heading toward the Searing Gorge or Kargath.",al={"why camp kosh","camp kosh location"}},{q="What did the ogres steal from the dwarves?",a="When Sigrun Ironhew's dwarven expedition fled Uldaman, they left supply wagons behind in the desert. Camp Kosh's ogres scavenged crates of food and weapons from them.",al={"dwarf supplies camp kosh","sigrun ironhew supplies","uldaman wagons"}}},ang={["race:Dwarf"]="Sigrun Ironhew's dwarven expedition left rations and weapons behind when it fled Uldaman. Camp Kosh's ogres took them.",["faction:Alliance"]="Alliance scouts on the northern route toward the Searing Gorge must watch for Camp Kosh's ogres. They ambush passing supply caravans."},kw={"badlands","camp kosh","dustbelcher","ogres","sigrun ironhew","uldaman"},rel={"zone:badlands","subzone:uldaman","zone:searinggorge","subzone:kargath","topic:alliance"},src={"Camp Kosh"}}
E["subzone:camp-wurg"] = {t="subzone",n="Camp Wurg",z="badlands",s="Dustbelcher ogres hold Camp Wurg among the Badlands crags. Their camps reach across much of the harsh region.",h="Dustbelcher ogres hold Camp Wurg among the Badlands crags.",sec={{t="A Dustbelcher Stronghold",b="Dustbelcher ogres guard Camp Wurg among the Badlands crags. It is one of their four main camps, with Camp Cagg, Camp Boff, and Camp Kosh. The ogres scavenge across the desert wastes and defend their rugged territory fiercely. Brutes and enforcers gather around crude fires and rough hides. Boss Tho'grun, their chieftain, has no permanent seat at Wurg. He roams the Badlands trails and watches over all four camps.",sp=0}},faq={{q="Who lives in Camp Wurg?",a="Dustbelcher ogres live at Camp Wurg, one of their settlements across the Badlands.",al={"camp wurg mobs","who is at camp wurg","who lives here"}},{q="Where is the leader of the camp?",a="Boss Tho'grun, chieftain of the Dustbelcher ogres, roams the Badlands trails between Camp Wurg, Camp Cagg, Camp Boff, and Camp Kosh.",al={"camp wurg boss","boss thogrun location","who leads camp wurg"}},{q="What other camps belong to this tribe?",a="The Dustbelcher ogres hold four main camps in the Badlands: Camp Wurg, Camp Cagg, Camp Boff, and Camp Kosh.",al={"dustbelcher camps","other ogre camps badlands","ogre settlements badlands"}}},kw={"badlands","boss tho'grun","camp boff","camp cagg","camp kosh","camp wurg","dustbelcher","ogre","wurg"},rel={"zone:badlands"},src={"Camp Wurg"}}
E["subzone:crypt-badlands"] = {t="subzone",n="Crypt",z="badlands",s="In the Badlands hills, an armored skeleton sits enthroned in a hidden tomb. Urns, chests, and an ancient sword lie beside the silent remains.",h="In the Badlands hills, an armored skeleton sits enthroned in a hidden tomb.",sec={{t="The Tomb of the Barbarian King",b="Southeast of Hammertoe's Digsite, an unmarked path climbs the hillside to the Crypt. Below, an armored skeleton sits on a stone throne in dark chambers. Beside the remains lies the Sword of the Barbarian King, among bones, urns, and forgotten chests. Miners and travelers search nearby gullies for dwarven ruins and riches, while the seated ruler's origins remain lost to the Badlands.",sp=0}},faq={{q="Where is the Crypt located in the Badlands?",a="The Crypt's entrance lies southeast of Hammertoe's Digsite. An unmarked path climbs the hill above the digsite.",al={"badlands crypt location","how to find badlands crypt","crypt entrance badlands"}},{q="Who is the skeleton sitting on the throne inside?",a="The armored skeleton is known as the Barbarian King. No surviving local texts tell who he was or how he ruled, so his story is lost to the Badlands.",al={"skeleton on throne","who is the barbarian king","crypt skeleton identity"}},{q="What is the sword next to the throne?",a="The sword is called the Sword of the Barbarian King. It rests beside the skeletal ruler as a grave marker from his warlike past.",al={"sword of the barbarian king","crypt sword","badlands throne sword"}},{q="Are there any quests associated with this crypt?",a="No customary tasks lead travelers into the crypt. It remains a hidden discovery for those exploring the cliffs.",al={"badlands crypt quest","why go to badlands crypt"}}},ang={["class:Warrior"]="As a warrior, you can pause before a fallen champion who died clad in plate. His mighty blade still lies beside him.",["race:Dwarf"]="As a dwarf, you find the crypt near active dwarven digsites. Its architecture and skeletal throne point to mysteries from before Ironforge's recent excavations."},kw={"badlands","barbarian king","crypt","hammertoe's digsite","sword","throne"},rel={"zone:badlands"},src={"Crypt (Badlands)"}}
E["subzone:dustbowl"] = {t="subzone",n="Dustbowl",z="badlands",s="In the Badlands, travelers cross the Dustbowl between Kargath and the Valley of Fangs. Its dry gullies and open ground are roamed by coyotes, buzzards, and rock elementals.",h="In the Badlands, travelers cross the Dustbowl between Kargath and the Valley of Fangs.",sec={{t="A Scorched Crossing",b="Camp Wurg marks the Dustbowl in the northwestern Badlands. Dry gulches cut through cracked clay, and harsh winds sweep grit across the open flatland. Cacti and scattered, gnarled trees cling to the barren soil.\n\nCoyotes prowl, buzzards circle overhead, and living rock elementals wander the rugged earth. Without a guide, crossing this wilderness is perilous. Camp Wurg offers a landmark amid the scrub, between Kargath and the Valley of Fangs.",sp=0}},faq={{q="Where is the Dustbowl located?",a="The Dustbowl lies in the northwestern Badlands, between Kargath to the west and the Valley of Fangs near the center.",al={"dustbowl location","where is dustbowl","dustbowl badlands map"}},{q="What creatures wander the Dustbowl?",a="Coyotes prowl the Dustbowl, while buzzards circle overhead. Rock elementals wander its stony ground.",al={"dustbowl mobs","what lives in dustbowl","dustbowl beasts"}},{q="What landmarks are found in the Dustbowl?",a="Camp Wurg is a landmark in the Dustbowl, between Kargath and the central Badlands.",al={"camps in dustbowl","camp wurg dustbowl"}},{q="Can any plant life survive out here?",a="Hardy cacti and scattered, gnarled trees grow in the Dustbowl despite its dry climate.",al={"dustbowl flora","plants in dustbowl"}}},ang={["faction:Horde"]="Just beyond Kargath, the Dustbowl is the first open wilderness Horde scouts cross when heading east into the Badlands."},kw={"badlands","buzzards","camp wurg","coyotes","dustbowl","kargath","rock elementals","valley of fangs"},rel={"zone:badlands","subzone:camp-wurg","subzone:kargath","subzone:valley-of-fangs"},src={"Dustbowl"}}
E["subzone:kargath"] = {t="subzone",n="Kargath",z="badlands",s="In the western Badlands, Kargath guards the Horde's foothold. The Kargath Expeditionary Force built the outpost on Warchief Thrall's orders, linking Horde holdings and preparing operations near Uldaman and Blackrock Mountain.",h="In the western Badlands, Kargath guards the Horde's foothold.",sec={{t="A Bastion in Hostile Territory",b="Kargath honors the Shattered Hand chieftain Kargath Bladefist. The outpost is the Horde's only settlement in Khaz Modan, surrounded by arid wastes, dangerous wildlife, and hostile dwarven factions. Its garrison gives travelers a refuge midway across the continent. From here, a flight master connects northern holdings such as the Undercity and Hammerfall with southern outposts such as Stonard and Grom'gol Base Camp.",sp=0},{t="The Expeditionary Mission",b="Warchief Thrall sent the Kargath Expeditionary Force to pursue two aims. Troops enter Uldaman's ancient titan halls to learn why Ironforge's Prospectors value the dig site so highly. Scouts also seek a route through the Searing Gorge into Blackrock Mountain. There they hope to strike Rend Blackhand's false 'Dark Horde' while facing the entrenched Dark Iron dwarves.",sp=0}},faq={{q="Why is this Horde town out in the middle of the Badlands?",a="Warchief Thrall ordered the Kargath Expeditionary Force to establish the outpost and secure a foothold in the region. The force investigates the dwarven dig at Uldaman and seeks a route into Blackrock Mountain to strike the Dark Horde.",al={"why is kargath here","purpose of kargath","who built kargath"}},{q="Who is Kargath named after?",a="Kargath honors Kargath Bladefist, the famed chieftain of the Shattered Hand orc clan.",al={"kargath name origin","who was kargath","kargath bladefist outpost"}},{q="Why are the flight routes from Kargath so important?",a="Kargath links northern Horde holdings such as the Undercity and Hammerfall with southern territories in Stranglethorn Vale and the Swamp of Sorrows.",al={"kargath flight path","why fly to kargath"}},{q="What threat is the garrison at Kargath preparing to fight?",a="The garrison faces local Dark Iron dwarves and investigates Ironforge's presence at Uldaman. It also prepares to strike Rend Blackhand and his Dark Horde in Blackrock Mountain.",al={"kargath enemies","who does kargath fight"}}},ang={["faction:Horde"]="Kargath is the Horde's only friendly fortress in Khaz Modan, with supplies, flight connections, and a base for strikes against Blackrock Mountain.",["race:Orc"]="As an orc, you see Kargath bear your chieftain Kargath Bladefist's name. Thrall's campaign from this outpost aims to destroy Rend Blackhand's Dark Horde."},kw={"badlands","blackrock mountain","expeditionary force","kargath","kargath bladefist","shattered hand","thrall","uldaman"},rel={"zone:badlands","subzone:uldaman","subzone:blackrock-mountain","zone:searinggorge","npc:thrall","zone:undercity","subzone:hammerfall","subzone:stonard"},src={"Kargath"}}
E["subzone:lethlor-ravine"] = {t="subzone",n="Lethlor Ravine",z="badlands",s="Black dragons roost and rear their young in Lethlor Ravine, deep in the eastern Badlands.",h="Black dragons roost and rear their young in Lethlor Ravine, deep in the eastern Badlands.",sec={{t="A Dragonflight's Bastion",b="Scorched plateaus rise around Lethlor Ravine in the eastern Badlands. Craggy walls shelter the black dragonflight’s nests. Fierce whelps crowd beneath the watch of larger drakes that breathe fire. Few travelers dare approach the ravine floor. Overhead, shadows mark winged predators circling among the rocky spires.",sp=0},{t="Mysteries in the Dust",b="Crystalline obelisks lie scattered among the crags beside the dragon brood. They are involved in a local chain of tasks, but their origin is not established.",sp=0}},faq={{q="What is Lethlor Ravine?",a="Lethlor Ravine cuts through the eastern Badlands, where black dragons nest among craggy walls.",al={"where is lethlor ravine","what is this canyon","lethlor ravine info"}},{q="Why are there so many black dragons here?",a="The black dragonflight roosts and rears its young among Lethlor Ravine’s sheltered, desolate rock formations, far from major civilized cities.",al={"why are there dragons in badlands","lethlor dragons","black dragonflight in badlands"}},{q="What are the crystal obelisks in the ravine?",a="Crystalline obelisks lie scattered through the ravine and are involved in a local chain of tasks. Their origin is not established.",al={"lethlor crystal towers","pillars in lethlor ravine","obelisks badlands"}},{q="Is Lethlor Ravine safe for travelers?",a="No. Flying drakes and aggressive whelps fill the ravine and attack trespassers on sight.",al={"can i walk through lethlor ravine","is lethlor ravine dangerous"}}},ang={["class:Hunter"]="As a hunter, you can test your marksmanship against fast-moving dragonkin and winged predators among Lethlor Ravine’s ridges and skies."},kw={"badlands","black dragonflight","drakes","lethlor ravine","obelisks","whelps"},rel={"zone:badlands","topic:black-dragonflight"},src={"Lethlor Ravine"}}
E["subzone:maker-s-terrace"] = {t="subzone",n="Maker's Terrace",z="badlands",s="At the Badlands' northern edge, Dark Iron dwarves hold the Maker's Terrace beside the pass from Loch Modan. Their open-air dig guards the way into Uldaman.",h="At the Badlands' northern edge, Dark Iron dwarves hold the Maker's Terrace beside the pass from Loch Modan.",sec={{t="Threshold of the Vault",b="From the pass out of Loch Modan, you cross trenches and scaffolds spread across the northern Badlands. The dig fronts Uldaman's entrance, an ancient vault built by the Makers. Travelers cross this exposed ground before reaching the halls below. Rival factions contest the approach as they seek a way into the ruins.",sp=0},{t="Dark Iron Occupation",b="Dark Iron dwarves patrol the ditches and perimeter, keeping outsiders from the dig. They seek the Makers' relics and power to dominate what lies beneath the earth. Their crews search the hillside for armaments, records, and other relics left by the ancient Makers. The sentries guard the route into Uldaman, and travelers who try to pass meet a hostile welcome.",sp=0}},faq={{q="Where is the Maker's Terrace located?",a="The Maker's Terrace lies in the far north of the Badlands beside the pass from Loch Modan. Its excavation surrounds Uldaman's outer entrance.",al={"maker's terrace location","where is makers terrace","how to find makers terrace"}},{q="Who controls the Maker's Terrace?",a="Hostile Dark Iron dwarves occupy and patrol the Maker's Terrace. They dig into the hillside and guard the approach to Uldaman.",al={"who is at makers terrace","makers terrace enemies","who controls makers terrace"}},{q="What is the purpose of the excavation?",a="The Dark Iron dwarves excavate Uldaman, an ancient titan complex, seeking relics and power over its depths. They search its vaults for machinery and secrets before rival factions can claim them.",al={"why are they digging here","makers terrace dig","what are dark irons looking for"}},{q="Is Maker's Terrace part of Uldaman?",a="Yes. The Maker's Terrace is the open-air excavation outside Uldaman, leading to its halls and caves.",al={"is this uldaman","makers terrace vs uldaman","terrace connection to dungeon"}}},ang={["race:Dwarf"]="As a dwarf of Ironforge, you may resent the treacherous Dark Iron clan's hold on the Maker's Terrace. Uldaman holds the deepest secrets of dwarven origins.",["profession:Mining"]="As a miner, you can see heavy ore workings in the quarries and earthworks cut into the sandstone cliffs."},kw={"badlands","dark iron","excavation","maker's terrace","makers terrace","titans","uldaman"},rel={"subzone:uldaman","zone:badlands","zone:lochmodan"},src={"Maker's Terrace"}}
E["subzone:mirage-flats"] = {t="subzone",n="Mirage Flats",z="badlands",s="East of Dustbelch Grotto, heat shimmers over Mirage Flats in the Badlands. Hungry predators roam the dry plateau beneath the desert sun.",h="East of Dustbelch Grotto, heat shimmers over Mirage Flats in the Badlands.",sec={{t="A Scorched Wasteland",b="East of Dustbelch Grotto, cracked red dirt runs beneath wavering heat. Few civilized souls linger on Mirage Flats. Giant buzzards circle overhead, watching for scraps left by ferocious ridge stalkers and crag coyotes that hunt in packs through the brush.",sp=0}},faq={{q="Where are the Mirage Flats located?",a="Mirage Flats lie in the central Badlands, east of Dustbelch Grotto. Travelers crossing between the western cliffs and eastern canyons pass over this sun-baked ground.",al={"mirage flats location","where is mirage flats","mirage flats map"}},{q="Why is the area called Mirage Flats?",a="Mirage Flats takes its name from the heat shimmering above its flat, stony earth. The wavering sights can disorient travelers crossing the wastes.",al={"why called mirage flats","mirage flats name meaning","heat mirage badlands"}},{q="What creatures prowl the flats?",a="Rabid crag coyotes hunt in packs, while ridge stalker patriarchs prowl the scrub. Giant buzzards circle overhead, waiting to feed on whatever falls in the dust.",al={"mirage flats mobs","what lives in mirage flats","beasts of mirage flats"}}},ang={["class:Hunter"]="As a hunter, you can track, study, or tame the aggressive beasts roaming these open plains. They include fierce ridge stalkers and coyotes hardened by desert survival."},kw={"badlands","crag coyote","dragon's mouth","dustbelch grotto","giant buzzard","mirage flats","ridge stalker"},rel={"zone:badlands","subzone:kargath"},src={"Mirage Flats"}}
E["subzone:uldaman"] = {t="subzone",n="Uldaman",z="badlands",s="In Uldaman, rival excavators and troggs now clash within the sealed halls. Beneath the northern Badlands mountains, this ancient titan vault holds the buried origins of the dwarven race, with stone sentinels still on guard.",h="In Uldaman, rival excavators and troggs now clash within the sealed halls.",sec={{t="The Vault of the First Creations",b="Titan watchers built Uldaman beneath the earth as a refuge and a place of research. Their first attempts to shape living stone made the misshapen troggs. They sealed them in stasis chambers, then tried again and created the stone-skinned earthen.\n\nThe deepest halls hold vital records, including the fabled Discs of Norgannon. Stonekeeper Archaedas and the giantess Ironaya guarded the vault. Dwarven legend says the earthen gave rise to the dwarven race, whose cradle lay buried and forgotten beneath the hills.",sp=0},{t="Excavation and Turmoil",b="Ironforge prospectors broke through Uldaman’s outer gates, and their pickaxes cracked open the stasis chambers. Awakened troggs flooded the upper tunnels, drove back the dwarven teams, and cut off the early dig sites. Dark Iron dwarves also marched into the ruins, seeking artifacts of supreme power for their fiery master, Ragnaros.\n\nNow rival dig teams, bloodthirsty troggs, and titan constructs battle in the deep shafts. The constructs awaken to smash any trespasser, whatever their clan or cause.",sp=1}},faq={{q="What is Uldaman?",a="Along the northern edge of the Badlands, Uldaman holds a vast underground titan facility built at the dawn of the world. The titans sealed failed experiments there and kept historical records, including the Discs of Norgannon.",al={"uldaman lore","what is this place","about uldaman"}},{q="Why is Uldaman important to the dwarves?",a="Dwarven legends say their ancestors, the stone-skinned earthen, were created in titan facilities like Uldaman. The Discs of Norgannon lie buried at the heart of the ruins, and decoding them could reveal the truth of dwarven origins.",al={"why do dwarves care about uldaman","dwarf origins","discs of norgannon"}},{q="Why are troggs infesting the ruins?",a="The troggs were the titans’ first attempt to shape stone servants. When the experiment failed, the titans sealed them in Uldaman’s stasis vaults. Ironforge miners accidentally broke into those chambers, freeing the troggs to spread through the corridors and surrounding mountains.",al={"where did troggs come from","why are troggs here","trogg origin"}},{q="What are the Dark Iron dwarves doing here?",a="Dark Iron dwarves search Uldaman for ancient titan artifacts. They hope to find powerful relics like the Discs of Norgannon for their elemental master, the Firelord Ragnaros.",al={"dark irons in uldaman","why are dark irons here"}},{q="Who guards the lowest chambers?",a="Archaedas, a massive stonekeeper, guards Uldaman’s lowest vault. He was charged with protecting the complex and its knowledge, alongside living stone constructs and golems.",al={"archaedas","who is the boss of uldaman","uldaman guardian"}}},ang={["race:Dwarf"]="As a dwarf, Uldaman touches the roots of your heritage. For generations, the Ironforge clans wondered where they came from. Dwarven legends point to stone discs buried beneath these trogg-infested halls.",["profession:Mining"]="Uldaman’s titan-worked halls hold rich veins of rare earth and metals untouched for millennia. Reaching them means braving trogg ambushes and awakened stone sentinels."},kw={"archaedas","badlands","discs of norgannon","earthen","explorers league","ironaya","titan","trogg","uldaman"},rel={"zone:badlands","topic:titan","topic:explorers-league","topic:trogg","zone:ironforge","zone:lochmodan"},src={"Uldaman"}}
E["subzone:valley-of-fangs"] = {t="subzone",n="Valley of Fangs",z="badlands",s="In the Badlands, a small camp keeps to the Valley of Fangs while predators roam nearby.",h="In the Badlands, a small camp keeps to the Valley of Fangs while predators roam nearby.",sec={{t="A Treacherous Pass",b="The Valley of Fangs runs between two great stone formations in the heart of the Badlands. Feral crag coyotes, prowling cougars, and vicious wolves stalk its dusty floor, so lone travelers face danger in the pass.\n\nA handful of wayward figures camp there. Martek the Exiled, a banished orc, keeps company with the goblins Rigglefuzz and Jazzrik. Far from the regional outposts, they tinker in seclusion.",sp=0}},faq={{q="Where is the Valley of Fangs located?",a="The Valley of Fangs lies in the central Badlands, between two massive natural rock formations south of the main northern ridgeline.",al={"valley of fangs location","where is valley of fangs","valley of fangs map"}},{q="Who lives in the Valley of Fangs?",a="Martek the Exiled, a lone orc, and his goblin companions Rigglefuzz and Jazzrik live at a small wayside camp.",al={"who is in valley of fangs","valley of fangs camp","valley of fangs npcs"}},{q="Why is the valley dangerous to travel through?",a="Cougars, wolves, and coyotes roam the valley floor and ambush wanderers in its narrow terrain.",al={"valley of fangs danger","valley of fangs mobs","what attacks you in valley of fangs"}},{q="Why did Martek and the goblins set up here?",a="Cast out and wandering the wastes, Martek the Exiled found a quiet, defensible niche between the rock walls. His goblin companions are willing to trade and tinker away from the prying eyes of major factions.",al={"why is martek here","why camp in valley of fangs","martek the exiled"}}},ang={["profession:Engineering"]="As an engineer, you may find goblin tinkerers at the Valley of Fangs camp, working far from the arid wastes' outposts.",["class:Hunter"]="As a hunter, you can track cougars and wolves through the valley and tame rugged Badlands beasts."},kw={"badlands","cougars","jazzrik","martek the exiled","rigglefuzz","valley of fangs","wolves"},rel={"zone:badlands"},src={"Valley of Fangs"}}
E["zone:badlands"] = {t="zone",n="Badlands",z="badlands",s="Dust storms sweep across the Badlands, where rival forces hold ground in dwarven Khaz Modan. Dark Iron dwarves, troggs, Dustbelcher ogres, and black dragonkin crowd this frontier between Loch Modan and Searing Gorge. Uldaman's titan ruins and the Horde stronghold of Kargath make it a crossroads.",h="Dust storms sweep across the Badlands, where rival forces hold ground in dwarven Khaz Modan.",sec={{t="A Bleak Frontier",b="South of Loch Modan's green hills, you enter a hot basin of barren flats and rugged ravines. Coyotes, cougars, and vultures roam the land, and fierce sandstorms can hide the horizon. Dustbelcher ogres keep crude camps across the plateaus. At Angor Fortress, the Dark Iron clan fortifies its hold and clashes with anyone who trespasses.",sp=0},{t="The Secrets of Uldaman",b="Among the northern bluffs lies Uldaman, an underground complex carved by the titan-forged earthen. Ironforge prospectors recently uncovered it, revealing monumental secrets about the ancient ancestry of the dwarven race. Their digging awoke hordes of vicious Stonevault troggs and animated earthen guardians. The creatures slaughtered the archaeological teams and turned the digsites outside into bloody skirmish grounds.",sp=0},{t="The Shadows of Kargath and Lethlor",b="The Horde holds one of its most precarious footholds in the southern Eastern Kingdoms here. Kargath, in the northwest, gives Warchief Thrall's forces a base to watch the rogue Dark Horde in nearby Blackrock Mountain. Far to the east, Lethlor Ravine cuts a treacherous chasm through the land. Beneath the mountains' shadow, black whelps and dangerous black dragonkin guard their brooding grounds.",sp=0}},faq={{q="Why is the Horde stationed in the Badlands?",a="Warchief Thrall ordered the Kargath Expeditionary Force to establish Kargath. Under Warlord Goretooth, the outpost gives the Horde a staging ground to strike Rend Blackhand and his renegade Blackrock clan inside Blackrock Mountain.",al={"why kargath","horde in badlands","what is kargath"}},{q="How do you get to the Badlands?",a="Alliance travelers can walk south from Loch Modan through the Maker's Terrace pass. Horde travelers must trek farther through Loch Modan's southern hills or cross Searing Gorge by its western mountain pass. Then they can use Kargath's flight master.",al={"getting to badlands","how to reach badlands","badlands entrance"}},{q="What is Uldaman?",a="Uldaman is a vast underground vault built by the ancient titans and their earthen servants. Dwarven prospectors recently excavated it in search of the secrets of dwarven origins, awakening buried earthen constructs and primitive Stonevault troggs. The ruin is now a deadly battleground.",al={"what's uldaman","uldaman dungeon lore","who made uldaman"}},{q="What are the black dragons doing in Lethlor Ravine?",a="Black dragons use Lethlor Ravine in the east as a breeding and nesting canyon. Drakes and whelps guard the clutch, which preys on wanderers and guards the eastern reaches against trespassers.",al={"dragons in badlands","lethlor ravine dragons","black dragonflight badlands"}},{q="Who controls Angor Fortress?",a="The hostile Dark Iron clan holds Angor Fortress south of Uldaman. From there, the clan conducts reconnaissance, contests the titan digsites, and battles neighboring ogres and surface explorers.",al={"angor fortress","badlands fortress","dark irons badlands"}},{q="Are there any friendly settlements for Alliance players here?",a="No fortified Alliance settlements or flight masters stand in the Badlands. Ironforge prospectors and solitary hermits keep scattered, fragile camps near the digsites. Alliance travelers must rely on Loch Modan or Searing Gorge for extensive supplies.",al={"alliance town badlands","alliance flight path badlands","friendly alliance badlands"}}},ang={["race:Dwarf"]="As a dwarf, you can seek answers about your ancestry in Uldaman. Discoveries about the titan-forged earthen reshaped dwarven understanding of history.",["faction:Horde"]="As a member of the Horde, you find your military sanctuary at Kargath, deep in Khaz Modan. The stronghold stands on the front line against the Dark Horde in Blackrock Mountain.",["profession:Mining"]="As a miner, you can find iron, gold, truesilver, and mithril in this arid land. Rare Indurium deposits lie in Uldaman and the surrounding terrain."},kw={"angor fortress","badlands","dustbelcher","earthen","goretooth","kargath","lethlor","troggs","uldaman"},rel={"subzone:uldaman","subzone:kargath","zone:lochmodan","zone:searinggorge","subzone:lethlor-ravine","npc:warlord-goretooth","topic:dark-iron-clan","topic:black-dragonflight"},src={"Badlands (Classic)","Badlands"}}
